window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_071"]={"n":"金幼孜","dyn":"明","poems":[{"t":"元夕赐观灯 其二","f":"七言律诗","c":["河汉沉沉霁景澄，蓬莱撚满九华灯。","青猊白象三千界，绮阁雕阑十二层。","花绣芙蓉浓艳吐，帘垂翡翠异香凝。","世人唯向云中见，遥望天门不可登。"]},{"t":"元夕赐观灯 其四","f":"七言律诗","c":["乐奏《韶》、《咸》宝扇开，遥瞻龙驭自天来。","九门香逐灵飙度，万国春随御气回。","綵凤高临青玉案，彤云轻护紫霞杯。","臣民共愿宸游乐，海内欢声溢九垓。"]},{"t":"元夕赐观灯 其六","f":"七言律诗","c":["中使传宣宴百官，佩声遥集五云端。","酒颁绿蚁开金瓮，馔鲙苍鳞奉玉盘。","宝帐春回频送暖，瑶台雪霁不生寒。","侍臣沾醉蒙恩德，更敕都人近御看。"]},{"t":"春日随驾北征次清河（永乐八年）","f":"五言律诗","c":["万乘统元戎，鸣銮出九重。","暖尘生辇路，晴雪照行宫。","旗影西山外，笳声落照中。","书生怀脱略，须敌万夫雄。"]},{"t":"早发清河","f":"五言律诗","c":["海色正苍凉，龙旗拂曙光。","雕戈寒映日，羽箭薄凝霜。","城阙云中近，关山笛里长。","天兵随杀气，万里扫搀抢。"]},{"t":"次怀来","f":"五言律诗","c":["羽檄通宵急，行宫出每迟。","漏声催鼓角，月影上旌旗。","风逐天香近，星随斗柄移。","中军严宿卫，传警尽熊罴。"]},{"t":"次万全","f":"七言律诗","c":["画戟雕戈映晚天，辕门尽日鼓喧阗。","御前视草冰生砚，帐下题诗雪满毡。","楼堞平空开朔漠，关门斗绝锁胡烟。","六军坐睹旄头落，何待阴山羽檄传。"]},{"t":"早发兴和","f":"五言律诗","c":["未晓戒严程，鸣弓度塞城。","川云随地起，野火杂星明。","虎旅听笳动，銮旗傍跸行。","草清沙路软，浑觉马蹄轻。"]},{"t":"誓师毕随驾回营中马上赋","f":"五言律诗","c":["万里阴山道，平原入望赊。","天营高日月，辇路净风沙。","宝马衔金勒，苍龙绕翠华。","阳和随处满，草色遍天涯。"]},{"t":"次归化甸","f":"五言律诗","c":["御前传檄罢，歇马卸鞍鞯。","日落双旌晚，云开万幕连。","边声回朔吹，尘色蔽胡天。","敌忾心犹切，长歌北伐篇。"]},{"t":"早发禽胡山","f":"五言律诗","c":["六师严号令，车骑肃前征。","塞月云中暗，胡尘雨后清。","沙鸡随箭落，野马近人惊。","咫尺闻天语，常依御辇行。"]},{"t":"次永安甸（即三汊口）","f":"七言律诗","c":["大幕尘清虏气摧，六师奏凯六龙回。","妖氛扫地旄头灭，御气浮空雉尾来。","武帐平临天汉回，戍楼遥傍朔云开。","行人笑指京华近，北望红云拥上台。"]},{"t":"奉和学士胡公春日陪驾同游万岁山 其一","f":"五言律诗","c":["凤辇游仙岛，春残花尚浓。","龙纹蟠玉砌，莺语度瑶宫。","香雾浮高树，祥云丽碧空。","五城双阙外，宛在画图中。"]},{"t":"奉和学士胡公春日陪驾同游万岁山 其八","f":"五言律诗","c":["暖露滋瑶草，轻飙动碧篁。","龙蟠知岁月，鹤唳识风霜。","凿谷通仙径，穿岩辟洞房。","回看城阙近，禁树晚苍苍。"]},{"t":"元夕午门赐观灯 其二","f":"五言律诗","c":["五夜开阊阖，千官引佩珂。","御烟浮宝篆，华月送清歌。","岁久君恩重，时平乐事多。","金吾知不禁，试问夜如何。"]},{"t":"元夕午门赐观灯 其三","f":"五言律诗","c":["鳌山新结綵，列炬照晴天。","箫鼓瑶台上，星河绛阙前。","綵妆千队好，绣簇万花妍。","欢赏陪鸾驭，还歌《既醉》篇。"]},{"t":"夏日喜雨写怀 其一","f":"五言律诗","c":["粉署依丹禁，城虚爽气多。","好风天上至，凉雨晓来过。","翠岛浮香雾，瑶池澹绿波。","九重閒视草，时复幸銮坡。"]},{"t":"夏日喜雨写怀 其二","f":"五言律诗","c":["夏过日初长，连朝雨送凉。","捲帘书帖静，开户燕泥香。","赐果来东阁，分冰近御床。","小臣叨侍从，屡得被恩光。"]},{"t":"夏日喜雨写怀 其三","f":"五言律诗","c":["玉堂清切地，潇洒出氛埃。","雨点疏疏过，天香冉冉来。","隔花莺历乱，近水燕飞回。","朝退有馀暇，新诗取次裁。"]},{"t":"元夕赐午门观灯 其一","f":"七言律诗","c":["鳌山高耸架层空，万烛烧春瑞气融。","星动银河浮菡萏，天垂琼岛绽芙蓉。","行行綵队穿华月，曲曲鸾笙度好风。","自是太平多乐事，君王要与万方同。"]},{"t":"元夕赐午门观灯 其二","f":"七言律诗","c":["凤辇初临鼓吹喧，千官环侍紫宸边。","九门灯火云霄上，午夜山河锦绣前。","春散炉烟浮树暖，月移宝仗映花妍。","从臣忝预传柑宴，既醉犹歌《湛露》篇。"]},{"t":"元夕赐午门观灯 其三","f":"七言律诗","c":["天上红云湿翠旗，楼前灯影动罘罳。","御筵花煖歌声近，紫禁风清玉漏迟。","中使传宣还赐果，词臣献赋更陈诗。","华夷尽道承恩泽，千载昌期际此时。"]},{"t":"元夕午门赐观灯 其二","f":"七言律诗","c":["天仗森森列宝台，教坊初进鼓如雷。","金莲夜放轻寒散，绛蜡春融瑞气回。","仙乐慢调双玉管，紫宸频上万年杯。","传柑岁岁承恩渥，感遇深惭负不才。"]},{"t":"元夕午门观灯应制 其十二","f":"七言绝句","c":["阊阖重重夜不扃，琼楼十二敞银屏。","东风一曲升平乐，此夜都人尽许听。"]},{"t":"三月十日随驾猎海子上奉简胡学士杨庶子","f":"七言律诗","c":["暖日融融静鼓鼙，条风拂拂动旌旗。","柳间饮马春泉细，花里闻莺昼漏迟。","近苑猎回犹赐馔，行宫朝罢更题诗。","晚来独向都城望，云拥蓬莱五色垂。"]},{"t":"扈从狩阳山次韵答胡学士","f":"七言律诗","c":["鸾舆晓出五城东，从狩儒臣载笔同。","日下苍龙随玉仗，道前宝马载雕弓。","苑松承露枝皆白，岛树经霜叶尽红。","向晚笳声催叠鼓，军门校猎气偏雄。"]},{"t":"扈从再狩武冈次学士胡公韵 其一","f":"七言律诗","c":["晓瞻行殿倚岧峣，步入高峰路更遥。","铁骑蹴云开御道，苍鹰掠野上层霄。","旌旄高下随山转，烟火依微隔树烧。","忝后词臣惭谫薄，几回扈跸逐行镳。"]},{"t":"北京八景 其六 西山霁雪","f":"七言律诗","c":["海上云收旭景新，连峰积雪净如银。","晴光迥入千门晓，淑气先回上谷春。","瑶树生辉寒已散，琼林消冻煖偏匀。","玉堂相对题诗好，移席钩帘坐夕曛。"]},{"t":"北京八景 其一 居庸叠翠","f":"七言律诗","c":["巀嵲天关复几重，龙飞凤翥势偏雄。","千山黛色落平野，万里烟光明远空。","峡口人行春雨外，树边鸟度夕阳中。","北巡记得随鸾驭，曾上云间第一峰。"]},{"t":"北京八景 其五 蓟门烟树","f":"七言律诗","c":["平野荒荒接蓟门，淡烟疏树碧絪缊。","过桥酒幔依稀见，附郭人家远近分。","翠羽落花行处有，绿阴啼鸟坐来闻。","玉京尽日多佳气，缥缈还看映五云。"]},{"t":"云山草堂为杨庶子赋 其一","f":"七言律诗","c":["闻道幽居近翠微，好山多与白云齐。","柳塘日煖花争发，门巷春深鸟自啼。","酒醒每临松下坐，诗成閒向竹边题。","一从射策金门去，风雨年年梦建溪。"]},{"t":"长林书屋为学士胡公赋","f":"五言古诗","c":["我昔游青原，闻子庐沧洲。","近瞰芙蓉山，遥睇大江流。","绕屋植嘉木，开轩面良畴。","繁阴夺炎夏，爽气回高秋。","庭除鸟雀静，白日人事幽。","牙签积架上，缥帙盈案头。","讲诵穷昼夜，奋力追前脩。","群言极探索，小大悉搜求。","藏脩既有时，俛仰随所由。","朝吟倚苍竹，夕览登高楼。","援琴酌白酒，盍簪聚朋俦。","抽毫落风雨，挥剑拂斗牛。","一朝齿乡校，战艺即见收。","高举薄霄汉，远览帝王州。","匡时展经术，所志在伊周。","清华职论思，秉笔赞鸿猷。","步趋迩禁闼，顾问纡宸旒。","侍从十五载，荷蒙恩宠优。","去年省桑梓，偶得寻旧丘。","徘徊抚林木，感叹非昔游。","沧波去浩浩，白云日悠悠。","鹿门未有期，小山不可留。","临风驻遐想，怅恍增烦忧。","因之寄图画，聊复写绸缪。","尚期返初服，白首同归休。"]},{"t":"辞剑图为学士胡公赋","f":"五言古诗","c":["楚平席僣伪，任邪斥忠良。","伍奢既就烹，子胥遂奔亡。","出疆适吴会，追者何太忙。","行行至江浒，欲渡津无梁。","邂逅得渔父，哀穷济以航。","感此脱危厄，解剑聊为偿。","父也义不受，长揖增慨慷。","嗟彼寰中人，结交布周行。","刎颈誓莫逆，笑谈出肝肠。","一朝婴祸患，变情非故常。","父也谅非旧，急难恤劻勷。","利害等丝发，万金一毫芒。","高风振颓俗，百世仰馀光。","夫子尚志节，抚图不能忘。","写之置座隅，怀古意何长。","斯人不可见，三复涕沾裳。"]},{"t":"清白堂为杨庶子赋","f":"古风","c":["关西昔华胄，太尉古名臣。","直节照简册，清风动冠绅。","遂令千载下，流光播无垠。","伟哉建安?，阀阅何嶙峋。","夫子负杰特，学术孰与伦。","蜚声起庠序，高步凌风云。","决科振场屋，射策登紫宸。","词垣清切地，列职逾十春。","瞻依近日月，蒙被恩宠新。","从容念先训，所志在忠勤。","于焉揭华扁，文藻䴡青旻。","左右列图史，退休时讨论。","庭空绝私谒，来往稀回轮。","兢兢慎操履，栗栗保贞纯。","冰壶湛秋月，玉雪含幽芬。","匪图淑来裔，庶以希前人。","蹇予沗侍从，托交谊弥敦。","耿耿怀补报，恒恐贻缁磷。","登堂仰休闻，企瞻愧后尘。","作诗写衷曲，聊以申同寅。"]},{"t":"惠迪斋为临川刘纪赋","f":"五言古诗","c":["西江有佳士，文采何陆离。","少小入庠序，所习书与诗。","兢兢循轨则，抑抑谨威仪。","顺理身逾泰，寡欲心自怡。","匪兹卜休咎，实以严操持。","天地有常运，寒暑不违时。","生人有常道，所志在秉彝。","内省苟无愧，安命复奚疑。","愚者昩厥理，蹈险去坦夷。","违天伐恒性，倒行兼逆施。","一朝罹显罚，宁复救颠危。","所以古贤圣，恳恳垂训辞。","斋居托令名，进脩诚在斯。","绩学匪空言，力行思有为。","乃者辞乡邑，吐气凌虹霓。","振衣游太学，揖让何委蛇。","及兹被宠命，筮仕固有期。","直道苟不回，志行宁有亏。","努力慎朝夕，永保期弗隳。"]},{"t":"酌泉斋为嘉静吴员外乃弟赋","f":"五言古诗","c":["昔有吴刺史，饮泉著清声。","廉贪励高节，千载扬芳馨。","闻孙家淦曲，结屋依岩扃。","青山列户牖，嘉木罗前楹。","流泉出砌下，一碧湛泓渟。","斋居诵遗训，仰止思继承。","白云荫芳润，皓月涵虚明。","永日惬幽赏，頫仰挹清泠。","一酌祛烦虑，再酌怡神形。","三酌沁肌骨，顿使心目清。","匪兹乐澹泊，实以固幽贞。","嗟彼寰中人，胡乃独营营。","沉酣嗜曲蘖，夜旦了不醒。","视此酌泉者，宁不畏惕惊。","蹇予慕脩洁，清华迩蓬瀛。","幸兹远氛浊，漱涤琼瑶英。","凛焉对冰雪，朝夕怀兢兢。","誓图坚晚节，补报竭忠诚。","因斯发佳咏，聊以寄高情。"]},{"t":"赠李伯高司训还庐陵","f":"五言古诗","c":["庐陵古名郡，风俗天下闻。","卓哉欧阳子，奋发振斯文。","声光被后世，至今仰馀芬。","惟子企前轨，力学究典坟。","栖迟三十载，布衣谁与群。","忽兹膺荐举，峨冠上金门。","授以郡博士，文采耀青云。","今晨别我去，怅然惜解分。","临岐重握手，酌以白玉尊。","朔风吹浩浩，雨雪何纷纷。","抽帆上南浦，行行近青原。","及家固云乐，况乃亲弟昆。","蹇予荷恩遇，谬忝职禁垣。","西江未同返，遥睇瞻丘园。","解佩为子赠，聊复申好言。","勖哉继先达，浮名何足论。"]},{"t":"梅窗为教授金原祺赋","f":"五言古诗","c":["严冬闭云阴，众卉各摧折。","瑶树粲佳花，绰约凌冰雪。","君子秉文教，终岁擅高洁。","岂期谢春荣，所志坚晚节。","觞咏日逍遥，琴书足娱悦。","愿言保贞姿，庶以绍先烈。"]},{"t":"三友轩为德清钮允高赋","f":"五言古诗","c":["种树必嘉种，取友必端士。","常木无坚姿，泛交少恒志。","之子慕清贞，列植异凡卉。","直干倚脩节，孤芳挺苍翠。","冰雪誓不渝，并立凌寒岁。","览物尚如此，托交宁有异。","君子思贱贫，小人怀势利。","管鲍夫何如，此道久沦弃。","尚期秉金石，庶以敦高谊。"]},{"t":"郊祀斋宿翰林奉柬诸同寅","f":"五言古诗","c":["大郊届严祀，致斋玉堂署。","衣冠集寮寀，及此谐良晤。","焚香对苍竹，促席坐深户。","东风昨夜来，厓雪消馀冱。","庭草抽细芽，新条发幽树。","感兹节候殊，忽令鬒成素。","顾惟负简陋，朴樕惭虚誉。","未能寡尤悔，但恐辜恩遇。","幸兹同职业，规益赖深助。","清谈夜未央，澹然销众虑。","对越实在兹，宁敢忘祗惧。","将事期无斁，庶以荅神祜。"]},{"t":"鲁林怀思诗为太常孔克准赋","f":"五言古诗","c":["尼山诞元圣，大道斯以彰。","删述著彝典，笔削明王章。","冠冕照日月，端拱居庙堂。","礼乐极崇报，万世垂耿光。","阙里建东鲁，阀阅何煌煌。","诗书启华胄，奕叶扬芬芳。","迢迢姑蔑墟，遗泽久弥昌。","于焉有裔孙，妙龄际时康。","一朝被恩眷，超擢居太常。","青云耀簪绂，仪羽簉鹓行。","眄彼洙与泗，源深流且长。","惕焉企先躅，引领增慨慷。","岂无蘋蘩荐，道远不得将。","云山浩漫漫，杏林郁苍苍。","徘徊感霜露，恻怆悲中肠。","写图寓深臆，怀思固难忘。","愿言绍先绪，庶以慰所望。"]},{"t":"梅所诗","f":"五言古诗","c":["君子谢时好，幽居恒晏如。","开轩种梅树，宛若临西湖。","托根既得所，不受纤尘污。","岁寒濯冰雪，粲粲明肌肤。","幽芳袭图史，疏影交座隅。","於焉企高洁，澹泊聊自娱。","一朝领文教，中道异所趋。","梦寐二十载，延想徒踟蹰。","素心谅可托，白首期不渝。","他时幸归老，庶以返其初。"]},{"t":"雪梅为婿袁大鹏赋","f":"五言古诗","c":["忆昨家居时，种梅绕书屋。","岁寒绽佳花，满林散芬馥。","玉肌耀彩云，缟袂承朝旭。","把卷时相亲，巡檐看不足。","一朝上蓬菜，幽赏更难复。","耿耿怀不忘，梦寐在林谷。","偶然披画图，览玩增踯躅。","维子爱重之，结交谊尤笃。","无为媚冶容，汨没随流俗。","脩洁慎自持，于以保贞独。","挂冠倘可期，吾将返初服。"]},{"t":"挽吕处士礼部尚书震之父","f":"五言古诗","c":["蓝田贵名胄，世德重高门。","处士乐嘉遁，夙昔行谊敦。","栖迟托韦布，所志在丘园。","积善逾恳恳，裕后尤谆谆。","贤嗣奉明训，绩学希前闻。","发身耀科第，践历扬清芬。","操持厉冰雪，穆若春阳温。","南宫进华秩，廊庙资经纶。","厚禄遂荣养，宠锡尤缤纷。","讵期惨风木，衔哀竟无言。","圣情重褒恤，锡命贲九原。","存殁被光耀，感此天地恩。","述德表贞石，遗风俨犹存。","作诗写哀些，于以告后昆。"]},{"t":"雅集图为邹侍讲仲熙赋","f":"五言古诗","c":["王氏昔贵盛，幽赏寓西园。","佳花杂芳卉，脩篁荫丛兰。","瑶林郁深秀，亭榭无嚣氛。","时雨被繁绿，好鸟鸣间关。","兴言念君子，列籍联衣冠。","光风汎瑶席，馀霭袭芳樽。","豆笾既有序，咏歌何纷纭。","杯至迭酬酢，剧谈有馀欢。","挥麈睇飞鸿，解缨濯流泉。","援琴度逸响，洒翰生云烟。","夷旷各有得，意适欲忘言。","遗风寄图画，高致邈难攀。","兰亭世已远，所托在斯文。","苏黄去已久，光价重玙璠。","抚事增永叹，徒此怀清芬。"]},{"t":"题杨谕德画竹","f":"五言古诗","c":["杨子居巷南，闭门绝车马。","种竹不计年，浓深密相亚。","朝回解冠佩，对之极潇洒。","檐端落晴雪，凉籁含深夜。","我时一相过，弦琴坐其下。","得句写琅玕，笑歌倾盏斝。","冰霜叹迟暮，寒暑频代谢。","悠悠十五载，念子知音者。","两京昨暌违，良晤此倾写。","玉堂灯火寒，看竹仍题画。"]},{"t":"贞寿堂诗","f":"古风","c":["白璧易为玷，寡居少完节。","宛宛令母仪，娟娟抱幽洁。","二十失所天，中道遭卼?。","秉心靡他适，誓死弗回折。","高堂何巍巍，翠柏凌霜雪。","遐龄介眉寿，莫景耀黄发。","有子足侍养，有孙足娱悦。","堂前綵衣舞，堂上旨甘列。","懿德及乡闾，清风敦阀阅。","载诵柏舟诗，永言播贞烈。"]},{"t":"赠萧医士","f":"五言古诗","c":["萧子擅医名，不假药石功。","以心运元气，斡旋掌握中。","娄生婴热疾，萧子抚其躬。","默运极冥搜，顷刻皆流通。","化热为清凉，去烦息呻恫。","勿药收奇效，名声播西东。","报谢却金帛，高谊邈难同。","一朝持大轴，来语玉堂翁。","为之发佳咏，浩思意无穷。"]},{"t":"赠李翊赴南京国学助教","f":"五言古诗","c":["子昔负奇气，携书游泮庠。","学成迈流辈，策足驰康庄。","袖然掇乡荐，职教居蜀邦。","乐育著成绩，升擢闽海旁。","讲道心靡懈，善诱极周详。","于兹复九载，化雨深门墙。","既最天官考，超秩严诠量。","谓子才力优，岂宜专一方。","分教登胄学，斯文有荣光。","时当仲冬候，旋载南京航。","河冰冻未坚，执别途路长。","翔风振林木，鸿雁鸣且翔。","徘徊不能去，浩歌慨以慷。","愿言厉初志，为国成俊良。","作诗写朋好，白首无相忘。"]},{"t":"春意图","f":"五言古诗","c":["春阳政和煦，众卉相滋荣。","名花艳秀质，丹霞濯朱英。","众鸟意颇适，䧺雌相和鸣。","大气流天地，物物同生成。","因兹观至理，谁能契中情。"]},{"t":"寿谖堂为德清屠生诚作","f":"五言古诗","c":["谖草树北堂，雨露日蕃滋。","慈母欣有托，抚玩心独怡。","门庭日无事，鹤发明春晖。","之子念母慈，致养及良时。","朝朝具甘旨，炫耀五采衣。","再拜献春酒，泛此黄金卮。","祝母多寿考，千岁忘忧思。","岁岁对谖草，愿母长不衰。","母寿不易得，子心将何为。","谨言与慎行，战兢当自持。","显扬报母德，不使声名隳。","归哉尚努力，惜此光阴驰。","引领日相望，重来应可期。"]},{"t":"筠轩为脩撰陈叔刚乃父作","f":"五言古诗","c":["闽中有佳士，翛然伟丰仪。","閒居澹无营，与世恒相遗。","开轩种修竹，岁久蕃且滋。","流云被柯叶，雨露涵幽姿。","清飙振苍玉，舞凤何委蛇。","直节静相偶，虚心久能持。","弦琴杂宫徵，戛玉声相随。","悠然发佳兴，觞咏无不宜。","幽赏谐淇澳，高风犹可希。","愿言保贞独，岁晏以为期。"]},{"t":"陈氏竹甘露","f":"五言古诗","c":["猗猗淇园植，罗生满阶庭。","夕光流素液，垂兹泫瑶英。","洒枝方泥泥，缀叶犹盈盈。","当阳殊未消，承风愈坚凝。","孰知太和世，涵泽被群生。","彼美君子者，素行此其徵。"]},{"t":"万竿烟雨图为侍读曾鹤龄作","f":"五言古诗","c":["平生爱佳竹，常有江南情。","忽此见新图，玩之有馀清。","千竿挺寒玉，一片潇湘青。","离离紫凤梢，尚与烟云平。","依微拂厓石，隐约入杳冥。","声杂瀑泉小，色映寒溪明。","茆亭亚苍雪，美韵谐琴声。","旁有灌木丛，鸟雀时喧鸣。","秋风即摇落，突兀枝交撑。","独高此君节，寒暑无变更。","不逐桃李芳，不随蒲柳零。","惟应松与柏，可以同坚贞。"]},{"t":"赠顾进士让南京刑部主事","f":"五言古诗","c":["蚤岁负超卓，毕力穷书诗。","一朝掇高第，历试将有为。","秋台与简擢，郎署秩匪卑。","兹焉涖旧都，圣心尤倚毗。","邦刑古所重，钦恤诚在兹。","慈祥察冤滞，谳议公是非。","伊昔虞舜世，皋陶称士师。","明刑弼至教，世乃登雍熙。","惟子居部属，致理诚所宜。","勉勉服古训，兢兢慎操持。","勖哉踵前烈，永矢期弗隳。"]},{"t":"湖山佳趣为黄博士赋","f":"五言古诗","c":["屏迹慕閒旷，素有高世姿。","结茅谢尘鞅，澹然心自怡。","湖光涵几席，山色临书帷。","游鱼戏文藻，好鸟鸣高枝。","横琴芳树下，濯足清涧湄。","开樽酌美酒，挥毫赋新诗。","缅怀百年内，谁复同襟期。","一朝际休运，忽与云壑辞。","荐书达名姓，文采何陆离。","昨来居太学，横经拥皋比。","群才资乐育，讲授忘渴饥。","出处谅不偶，隐显固有时。","相期贵努力，补报方在兹。","他年谢簪绂，庶以慰心思。"]},{"t":"中秋宴集分韵得九字","f":"五言古诗","c":["圣皇抚区夏，省方事巡狩。","蹇予沗侍从，亦获效奔走。","杪春始驻跸，和气动郊薮。","良辰奉鸾驭，周览遍丘阜。","穷幽摭奇秀，幸免载刍糗。","寒暑倏更换，星虚已届酉。","於焉属秋半，宴会集寮友。","肴羞列长席，时果荐芳豆。","开尊对明月，序齿论先后。","灏气满琼楼，寒光达虚牖。","遥空净纤翳，河汉斜临斗。","零露浥丛兰，凉飙振疏柳。","盍簪有真乐，飞觞屡呼酒。","諠哗竞酬酢，笑语或扬肘。","分韵各有题，谁能为击缶。","鄙词愧珠玉，刬削惭芜莠。","俛怀际休运，感激恩尤厚。","毕力图补报，矢心期白首。","沗兹谐宿好，托交岁年久。","切偲赖启沃，洗濯脱尘垢。","追陪青琐闱，出入喜相偶。","旅怀顿宽释，忧思亦何有。","良宵兴未终，既醉犹携手。","南楼桂始花，东园菊方茂。","登临有佳约，相期在重九。"]},{"t":"九日宴集分韵得驶字","f":"五言古诗","c":["良辰不易得，流光疾如驶。","我行沗扈跸，三时留帝里。","倏兹届重九，朋从皆客子。","邀我开清宴，烹羔脍鲜鲤。","时蔬间枣栗，罗列亦盈几。","紫萸汎新酒，馨冽胜腊蚁。","喧呼热中肠，笑谈忘鄙俚。","酣歌引长剑，光芒照秋水。","仰视天宇宽，商飙飒然起。","候雁届新寒，霜菊犹含蕊。","遥岑晚逾碧，西山净如洗。","登高信非远，骋望增悬企。","幸兹会文饮，劝酬助深喜。","群公烂词藻，清芬播兰芷。","殷勤写衷素，抱拙惭虫技。"]},{"t":"赠友人谢绳正还新淦","f":"五言古诗","c":["忆我丱角初，携书侍严父。","访君沧洲曲，握手遂良晤。","碧梧挺高标，金兰托深契。","砚席幸有托，寒暄同起处。","朋情谢新益，丽泽惬衷素。","悠悠金石交，历历岁年莫。","东西各驱逐，冠盖何由聚。","南宫沗科甲，青云忽高举。","叨承侍从荣，出入诚何补。","今春别京国，北狩随鸾驭。","回望南天云，遥睇故园树。","凭高谩踌躇，对景增延伫。","君从梁宋来，邂逅慰羁旅。","天涯故旧情，镫前牢落趣。","时蔬荐辛盘，肴核侑芳醑。","剧谈夜未央，移席月当午。","但惜欢会难，宁知别离苦。","揽袂听晨鸡，候此秋天曙。","我复趋承明，君还故乡去。","鸿雁正南飞，商飙动砧杵。","分携五云馆，翘首金台路。","望望不见君，相思渺何许。"]},{"t":"蒋御医静学斋","f":"五言古诗","c":["伊人抱冲素，而有冰雪姿。","斋居谢尘垢，恒以静自怡。","图书盈几案，涵泳窥圣涯。","幽观契玄妙，昕夕忘渴饥。","寒暑更代谢，人事有盛衰。","万变恣纷扰，操存谅不移。","于焉企遐轨，俛与先哲期。","匪图富经术，复此专国医。","金门振高步，永怀扩所施。","勖哉励初志，作诗效箴规。"]},{"t":"挽永嘉吴原范因其子翰林庶吉士吴志文之请","f":"五言古诗","c":["昔人志幽独，皎皎冰玉姿。","穷居阅今古，言动无愆违。","力行敦孝友，耿介恒自持。","箪瓢澹无虑，韦布聊栖迟。","翰墨有馀暇，吟咏多新诗。","怀玉匪求售，末俗宁相知。","讵期溘朝露，遐逝竟莫追。","乡闾增永叹，亲友含悽悲。","承家幸有托，显扬方在兹。","太史述潜德，千载昭铭词。"]},{"t":"静闇为黄学士尊人赋","f":"五言古诗","c":["端居谢尘鞅，屏迹卧柴荆。","布衣乐嘉遁，箪瓢澹无营。","幽思契玄化，冥搜观物情。","神閒志先定，寡欲心自宁。","琴尊谐夙赏，水木涵馀清。","檐端白云下，芳径春草生。","永惬丘园趣，终辞圭组荣。","含光保贞固，养德崇令名。","吾生愧扰扰，遐想寻鸥盟。"]},{"t":"分题得秋浦孤帆送友人","f":"五言古诗","c":["疾风吹人寒，清霜肃天宇。","澄河浩漫漫，抽帆上秋浦。","汎汎淩雄涛，摇摇转孤屿。","川途坐超忽，飘飖惊鸿翥。","舟子誇利涉，中流喧笑语。","谁识倚篷人，恋阙时延伫。"]},{"t":"颐庵为祭酒胡公赋","f":"五言古诗","c":["君子志古道，中心常晏如。","一室绝尘想，湛若凝冰壶。","幽思契玄化，静观识盈虚。","于以求所养，揭颐当座隅。","匪徒兹口实，养德与之俱。","闲邪靡他适，步履由康衢。","翼翼谨仪度，周旋慎起居。","言寡行弥笃，体胖心自舒。","畅情发佳咏，随意读古书。","清风在几席，翰墨足自娱。","挥弦白云下，酌酒鸣禽呼。","䴡泽洽髦士，咏歌追舞雩。","芹藻沐时雨，桃李亦芬敷。","於焉陶圣化，沛然乐有馀。","愿兹保贞独，白首期无渝。"]},{"t":"素闇为邹侍讲仲熙赋","f":"五言古诗","c":["结发已学道，而有高世姿。","衡门远氛浊，韦布聊栖迟。","黾勉事耕稼，蔬食甘藿藜。","中年遘休运，遂与林壑辞。","辟雍起名誉，卓为学者师。","超登列清要，侍从职论思。","忠诚弥激切，耿分恒不移。","俛仰靡愧怍，操存无外驰。","安行任所适，进退何委蛇。","图书列左右，翰墨复在兹。","沈潜探幽赜，涵咏窥圣涯。","孔子贵知命，顺理无不宜。","孟轲养浩然，力行复何疑。","尚友千载士，圣贤以为期。"]},{"t":"乐琴书处为沈民则学士赋","f":"五言古诗","c":["公本布衣士，世家在东吴。","襟怀敌冰玉，所乐琴与书。","牙签插满架，中有万卷储。","潜心究坟典，隽泳周孔腴。","矻矻忘岁年，昼夜穷卷舒。","兴来操孤桐，逸气凌八区。","寒泉出幽谷，清飙汎庭除。","一弹复一咏，沛然乐有馀。","栖迟三十载，仁仰恒晏如。","一朝去乡里，声价重璠玙。","载笔青锁闼，待诏承明庐。","光华依日月，荷沐恩宠殊。","蹇予沗侍从，出入联佩琚。","朝回访官舍，文字聊足娱。","弦琴坐芳树，洗盏酌清酤。","白鹤为起舞，酣歌剧欢呼。","嗟彼寰中人，此乐谁能俱。","惟公与我辈，职业侪文儒。","乾坤并生育，雨露均涵濡。","感此圣恩厚，补报将焉图。","愿言竭忠荩，白首期无渝。"]},{"t":"日省斋为驸马赵晖赋","f":"五言古诗","c":["君子秉高志，夙负冰玉姿。","斋居静无哗，玩习书与诗。","兢兢日自省，名贤为之师。","力行务忠信，跬步恐或违。","讲授资劘切，宁敢怀自欺。","黾勉竟朝夕，念兹复在兹。","弘毅期远到，一息罔有亏。","作辍或靡常，德业因以隳。","况乃托戚里，忠孝实所资。","嘉猷思献纳，仰图赞雍熙。","作诗匪为颂，庶以效箴规。"]},{"t":"赠孙博士致仕还丰城","f":"五言古诗","c":["孙君我乡里，十载居桥门。","雅志尚古道，布衣振斯文。","群才资乐育，仰钦博士尊。","讲论既不竭，考较良已勤。","小大各有成，宁复遗斧斤。","况闻笃义方，有子才且贤。","伯也领司牧，季也登词垣。","联翩耀文彩，宛若鸾凤骞。","三朝偕际遇，涵沐雨露恩。","忽兹去荣养，投簪赋归田。","纶音重褒锡，龙章焕缤纷。","骊驹戒明发，祖饯相攀援。","遥遥睇南浦，江流汎沄沄。","桑梓故无恙，松菊今尚存。","上堂接宾亲，入室抚儿孙。","閒居乐有馀，逍遥毕晨昏。","蹇予荷恩遇，侍从三十春。","白首冒荣禄，补报图拳拳。","故乡未回往，中情何由宣。","因兹写长句，聊以道慇勤。"]},{"t":"赠杨景衡致仕还永嘉","f":"五言古诗","c":["早岁负经术，文采耀儒绅。","明廷忽登荐，熙运逢昌辰。","首选夏官属，再擢领司勋。","九载绩称最，超迁佐名藩。","优优敷治理，黾勉勤咨询。","扬历三十载，践履思弥敦。","及兹登七秩，陈词乞归田。","圣情特允许，优老怀旧人。","清晨别阊阖，冠盖拥青云。","丝竹沸华筵，飞觞促行轮。","迢迢踰大河，渺渺涉长津。","乔林翳桑梓，竹树荫云泉。","别墅日成趣，猿鹤时相亲。","良辰集宾友，谐咏乐琴尊。","以兹保迟暮，眉寿绵千春。","永言写朋好，终始期勿谖。"]},{"t":"百日怀幼子武安","f":"五言古诗","c":["尔亡忽百日，无日不念尔。","行想尔追随，坐想尔游戏。","食想尔同桉，卧想尔同被。","清晨送我朝，未晚候我归。","逢迎与应荅，无不解人意。","如何遽夭阏，长往隔人世。","悲号彻上苍，抱痛切肝肺。","骨肉恩谊深，谁能即捐弃。"]},{"t":"挽凤阳周处士","f":"五言古诗","c":["士有慕恬素，习隐居田庐。","逍遥毕冬春，衣食自有馀。","孳孳轸穷匮，积善乃其图。","饬躬务俭勤，淑子惟诗书。","青云起步武，扬历陟要途。","及兹膺茂典，宠锡先亲俱。","恩荣及存殁，封秩偕鸿胪。","皇天报不爽，阴骘默与符。","铭文属太史，琢石崇丘墓。","桓桓松柏间，雨露深涵濡。","流庆未涯涘，浩若江海储。","昭兹贻后人，永世期不渝。"]},{"t":"讷斋为泥田周仲升作","f":"五言古诗","c":["君子尚古道，制行戒多言。","谨口不妄发，恒以讷为先。","酬酢合典则，终身远尤愆。","交游重敦朴，乡里推仁贤。","嗟彼寰中人，辨给若涛翻。","往往速咎戾，身名弗自全。","以兹贵守默，操制若管键。","高斋揭华扁，图史相周旋。","往来接朋好，终岁谢尘喧。","愿言服古训，永永期弗谖。"]},{"t":"赠杨允嘉还建安","f":"五言古诗","c":["华胄出关西，宦谱何煌煌。","声光照闽越，庆泽深且长。","少傅我知己，早年登玉堂。","风云际嘉会，千载符明良。","表仪动朝著，事业辉岩廊。","报国竭忠荩，治家敦义方。","令子皆伟器，清标重圭璋。","趋庭受经训，力学攻文章。","来往申定省，煜然多令望。","季也始弱冠，明珠异非常。","丰姿玉雪瑩，行美芝兰芳。","孝友出天性，诗书能自强。","时时肯过我，恭敬不暂忘。","周旋情恳恳，应唯声琅琅。","有如丹穴雏，羽仪绚朝阳。","又如千里驹，矫首欲腾骧。","我实爱念之，期待不可量。","昨者奉亲命，言旋归故乡。","侵晨向我别，欲去仍傍徨。","吾观公卿间，子弟空昂藏。","礼义漫不省，况乃资显扬。","念子好兄弟，承家相颉颃。","盛时须努力，学问无怠荒。","岂徒慰亲志，足以绍前光。","高高青云步，拭目看翱翔。"]},{"t":"凝秀楼为都御史邵玘作","f":"五言古诗","c":["君子秉纯孝，至和毓嘉祥。","重屋荐灵草，郁郁休气翔。","玄云被紫盖，丹霞沃太阳。","煜煜铜池秀，粲粲瑶圃芳。","轮囷异众卉，五色耀奇章。","岂伊昭行美，实以著休光。","况逢圣明世，位秩尤显扬。","属兹托邦宪，毅然振宏纲。","奋威薄鹰隼，除暴驱豺狼。","蜚声播畿甸，美誉驰岩廊。","拳拳励忠孝，勉勉赞时康。","昕夕期弗替，终誉思永臧。"]},{"t":"赠钟观伯司训新淦邑庠","f":"五言古诗","c":["为士贵立志，志立名乃成。","所以贤圣徒，尚志尤兢兢。","维子我同里，祖父实相知。","弱冠志己殊，昼夜穷书诗。","春秋绍家学，讲究探玄微。","明经夙抱负，应聘来京畿。","金门特召试，辞藻何陆离。","裒然居上第，侪辈咸相推。","翩翩持教铎，去作淦庠师。","清晨来告别，执手聊蹰踟。","骊驹且未动，尽此黄金卮。","大河日东注，白云正南驰。","朝经直沽北，暮驻长淮西。","钟山屹相望，庐阜雄且奇。","九江既浩荡，南浦何逶迤。","洪都集冠盖，车马纷往来。","弥楫剑江涘，舣棹萧水湄。","金川对玉笥，佳气含朝晖。","诸生集衿佩，瞻拜盛容仪。","舍菜谨趋谒，揖让生光辉。","升堂闻丝竹，宴会及兹时。","优游敷文教，作育怀切偲。","士风振颓靡，俗化厚民彝。","末学惩剽窃，弥文戒夸毗。","由兹兴治理，简拔有所资。","勖哉志道德，永矢期勿隳。"]},{"t":"悦琴轩","f":"五言古诗","c":["人生穹壤间，所好百不同。","好之得其正，德义日以充。","所好昵於邪，败德隳厥躬。","惟此方寸内，邪正恒相蒙。","君子履正道，秉志宜专攻。","理欲潜几微，毫发宁相容。","如彼耨苗者，莠去苗乃丰。","又如艺芝兰，棘剪兰始浓。","美恶若黑白，讵可昧所从。","惟尔负英迈，阀阅出名宗。","衣冠振江右，诗礼夙所崇。","尔亲我故交，契谊超凡庸。","眷言托姻好，得尔谐乘龙。","年来居贰室，契阔心忡忡。","去冬来省谒，晤语惬寸衷。","或时闻挥弦，悠然豁心胸。","凄清凌别鹤，飘飖逐游鸿。","委蛇合宫徵，满坐声沨沨。","神舒情转怿，体胖心自融。","於焉禁邪僻，蝥贼敢内讧。","尔能知好尚，德义宜兼隆。","所期力学问，持身秉谦冲。","出入先孝弟，周旋必敬恭。","惟学可明德，惟勤乃有功。","岁华易荏苒，流光若转蓬。","及时宜努力，黾勉毋怠慵。","蜚声绍先世，令誉垂无穷。"]},{"t":"鸿胪寺卿王善父哀挽","f":"五言古诗","c":["壮游去乡邑，卜筑居燕城。","中年谢轮鞅，遁世不求名。","布衣自萧散，风月娱幽情。","杖履随所适，壶觞时独倾。","诗书课诸子，笑谈集良朋。","翛然忘世虑，欣戚了不惊。","春秋馀六秩，乘化忽长征。","令子遘兴运，致身登明庭。","九重锡褒秩，追赠列九卿。","天章耀龙采，云汉昭日星。","大史最潜德，墓道揭新铭。","缙绅述哀挽，沨沨扬嘉声。","流庆殊未艾，千载想继承。"]},{"t":"山溪小隐为周时立赋","f":"五言古诗","c":["梧山郁苍苍，沂溪流瀰瀰。","溪山两奇绝，居有泥田里。","里中有著姓，衣冠数周氏。","君子乐在斯，恂恂谨操履。","力田充食衣，积学穷经史。","绕庐树桑麻，缘阶艺兰芷。","开窗白云来，挥弦清风起。","门深驻山光，庭虚湛流水。","宾朋或时过，觞豆同乐只。","酒酣赋新诗，歌咏谐宫徵。","悠然适嘉趣，达生契直理。","蹇予迫衰暮，役役果何似。","侍从三十春，贪荣昩知止。","况兹乏禆益，訹惕久未已。","挂冠倘可期，吾将返其始。","来往山溪间，庶以终馀齿。"]},{"t":"礼部新建诸卿设宴落成遂赋此","f":"五言古诗","c":["南宫壮巍巍，落成在今日。","笾豆秩礼筵，衣冠集俦匹。","献酬各有仪，谐笑忘坦率。","千载幸遭逢，昌辰庆文物。","成礼贵无愆，终焉敢怠忽。"]},{"t":"六月二十七日早朝奏孟秋时享","f":"五言古诗","c":["孟秋届时享，太常严斋沐。","圣主秉深诚，诘旦兴犹夙。","高阙䴡繁星，彤墀散明烛。","百寮谨祀事，祗命咸属属。","所期荅神庥，庶以臻福禄。"]},{"t":"送周时立归文江","f":"五言古诗","c":["远游送将归，翩然辞国都。","迢迢越山川，靡靡涉长途。","秋风动原野，残暑犹未除。","玄蝉号树端，候雁翔且呼。","岂伊念朋好，况复怀友于。","停杯且未别，握手谩踟蹰。","西江几千里，云水渺重湖。","子行日以远，会面日以疏。","及家虽云乐，我怀将何如。","旧乡未即返，南望增郁纡。","归哉倘相忆，为我致双鱼。"]},{"t":"雨叹","f":"五言古诗","c":["入秋五六日，风雨连夜朝。","屋漏水过膝，路滑泥没腰。","庭花半憔悴，田稼亦飘摇。","城中粟已贵，城外无归樵。","安得捲痴云，太阳䴡九霄。","使我开怀抱，无复忧早朝。"]},{"t":"山东盐运司副使萧鹏举挽诗","f":"五言古诗","c":["西昌有南溪，著姓曰萧氏。","传家本淳朴，积累自先世。","维公实亢宗，少小拔其萃。","孝友本天性，急难志不匮。","拳拳重手足，同居笃恩谊。","和气蔼门闾，紫荆兆嘉异。","一朝起林壑，浩然舒壮志。","待诏金马门，辞华著光䴡。","承恩佐名郡，涖官益严厉。","布衣与蔬食，俭素若寒士。","被谴忽远去，曾不怀怨怼。","荣辱恬不惊，夷险惟一致。","再起应时需，黾勉服官事。","岁课每先期，商民有遗利。","方兹图报称，胡乃遽捐弃。","室空无长物，缊袍遗箧笥。","见者为嘉叹，闻者增歔欷。","春秋更代谢，九原悼永逝。","令子志显扬，袖然掇高第。","近者来京师，一见非凡器。","昊天怀罔极，孝诚实深至。","乞我为挽辞，屡请不一置。","忆昨公仕时，我忝居禁侍。","两京曾晤面，幸获论乡契。","缙绅仰风裁，吏民称善治。","岂知十载间，忽忽如梦寐。","自古各有尽，圣贤皆如是。","令名可长存，死生那足计。","公归可无憾，贻后永无替。","殷勤写长诗，临风发深喟。"]},{"t":"挽周生涣","f":"五言古诗","c":["周生文江人，来作金台客。","负此英妙年，读书翰林宅。","辛勤阅冬春，讲诵穷朝夕。","昼倦忘渴饥，夜卧不就席。","文采照珊瑚，星斗蟠胸臆。","摛词已成章，篇翰稍堆积。","语言不妄发，居处恒谨饬。","事长秉谦恭，事亲循礼则。","布衣不屡更，蔬食无厌斁。","里巷少交游，缙绅幸知识。","閒过询所业，渐喜有进益。","岂知自去春，遽为二坚迫。","淹延逾岁月，形容就枯瘠。","兀坐或终朝，凭几或终日。","未忘亲笔砚，犹能检书籍。","临终声琅琅，从容具盥栉。","溘焉从此辞，哀乐异今昔。","骨肉增痛悲，亲知殊怆恻。","寒暑互往来，时序迭更易。","鸿雁正南翔，原野迥萧索。","兹辰返灵榇，祖送临道侧。","山川邈悠悠，魂魄将何适。","故乡日在望，行矣即窀穸。","颜蹠异寿天，善恶岂俦匹。","生年虽未多，已能踵前迹。","百年会有终，令名垂无极。","今古瞬息间，那足较失得。","生去日已远，我怀讵能释。","为生述此辞，庶以慰存殁。"]},{"t":"瞻松阁","f":"五言古诗","c":["严陵有陈氏，弟昆惟三人。","伯也嗣先绪，理家俭且勤。","仲也笃问学，起家列朝绅。","季也钟友爱，器宇温且淳。","三人心不异，夙昔均孝亲。","亲殁知几载，至今衔酸辛。","伯也怀永慕，种松绕孤坟。","坟前构高阁，繁阴蔽青云。","朝望松与对，暮处松为邻。","松间日来往，重壤贲九原。","时祭陈俎豆，謦欬若有闻。","风声起悽怆，雨露秋复春。","亲去日已远，子怀难重陈。","但使松益茂，爱护崇本根。","世世勿剪伐，永远扬清芬。"]},{"t":"浦云楼为罗宗器赋","f":"五言古诗","c":["豫章有佳士，磊落超常流。","久居厌諠杂，复此构崇楼。","突兀倚云表，翚飞凌斗牛。","绮窗间疏牖，灏气相荡浮。","西山与南浦，景物澹以幽。","朝登发佳兴，夕览舒烦忧。","宾朋日来往，歌咏同倡酬。","临风操猗兰，拂席看吴钩。","閒来诵坟典，子史兼穷搜。","岂惟绍先绪，实以光前脩。","昨者来京国，感子意绸缪。","索我题佳句，未能为淹留。","离思郁中肠，倏已及高秋。","谩兹托缣素，写怀寄沧洲。","他时倘归老，尚期寻旧游。"]},{"t":"送贡士邹文选南归","f":"五言古诗","c":["鸿鹄腾九霄，骐骥驰万里。","之子怀远图，学古希名士。","朅来与计偕，志欲取青紫。","殊方会贤俊，冠盖何旎旖。","战艺夺文场，誓将掇高第。","青云忽蹭蹬，逸足淹泥滓。","怀宝虽难售，抱器宁终秘。","归哉不可留，翩然去知己。","故乡渺江右，茫茫隔云水。","朝回一相送，怀抱殊礧磈。","徘徊不能别，何以写深契。","愧无千金赠，为子壮行李。","千金未足多，赠言重莫比。","须知九仞山，功成少一篑。","从兹更努力，慎无中道止。","贾董亦何人，垂名耀青史。","明当继芳躅，并驾骋遐轨。","日月悬中天，流光疾於驶。","相见在几时，重来勿淹滞。","望子翔青霄，庶以慰遐企。"]},{"t":"赠孔秉中考满复任郾城","f":"五言古诗","c":["先圣有孙子，家住西江湄。","积学企前轨，文采何陆离。","一朝膺鹗荐，飞步凌天池。","风云际嘉会，海宇同雍熙。","承恩佐名郡，莲幕暂栖迟。","牛刀虽小试，赞画靡不宜。","所贵在施设，宁惭职位卑。","宦游逾六载，朝夕任驱驰。","雅操厉冰檗，清苦恒自持。","寸心悉民隐，闾里无怨咨。","今秋辞洛邑，考绩来京畿。","铨曹严黜陟，三考固有期。","及兹命复职，庶以慰民思。","蹇予同里闬，托好深相知。","阔别已十载，道远音问稀。","都门一相见，握手心怡怡。","张灯话畴昔，有如消渴饥。","胡为不暂住，遽此叹睽离。","寒风正萧索，翘首雁南飞。","殷勤酌别酒，聊以写心私。","人生百年内，会合能几时。","愿期树嘉政，赠言比箴规。"]},{"t":"赠熊元节还南京","f":"五言古诗","c":["熊君负经术，早岁登青云。","素承明主知，超擢中朝臣。","继闻陟大理，奉命专咨询。","风声振吴越，次第苏疲民。","锄奸去豪猾，刬凶格顽嚚。","遂令东南郡，皞皞被皇仁。","圣情日虚宁，屡敕嘉劳勤。","三载积忧惧，驰情悬紫宸。","及兹奏对日，款慰尤谆谆。","申命职宪纪，荣光动朝绅。","南台既专任，委寄真殊伦。","绣衣明白日，清霜肃阳春。","岂惟戢贪墨，实以绳谬愆。","况闻澄清地，表率由一身。","惟君秉直谅，操履端且纯。","屹然重时望，所至扬清芬。","蹇予忝朝列，交谊夙所敦。","睽违渺南北，梦寐劳心神。","幸兹谐簪盍，晤对逾兼旬。","忽闻别我去，恻恻难为言。","骊驹发前路，遥瞻动芳尘。","衣冠拥广陌，丝管一何繁。","握手且未辞，尽此黄金尊。","人生会合间，百岁若转轮。","黾勉图报称，致身在君亲。","永怀保终誉，景仰希前闻。","庐陵多达士，至今耀斯文。","忠节著宇宙，千载垂不泯。","勖哉践古道，永矢期勿谖。"]},{"t":"赠周子瓛致仕还永丰","f":"五言古诗","c":["驱车欲何适，驾言归故乡。","朋游具觞豆，饯送临周行。","忆昨佐花县，志气殊非常。","琴堂席未暖，行役嗟靡遑。","京华历寒暑，鬓发皓已苍。","布衣与蔬食，澹泊常自将。","只今七十馀，谢事何匆忙。","为感圣恩厚，悲歌激中肠。","徘徊不能别，念此故意长。","山川邈迢递，大江浩洋洋。","去途日已远，驰景曜征裳。","愧无千金赠，为子增慨慷。","归哉慎自保，南北永相望。"]},{"t":"思全室为李士文赋","f":"五言古诗","c":["人生天地间，禀受良有偏。","七情失其正，六脉为之愆。","因兹致疾疚，危弊纷相联。","所以古先圣，医药使其全。","姑苏有佳士，仙李毓庆源。","上窥黄农秘，术业尤精专。","兢兢念疲癃，恻恻闵危颠。","神楼有奇效，一匕生气旋。","杏林蔼春意，橘井流香泉。","苏耽不可见，董奉亦可仙。","超焉继高躅，宁为利禄牵。","朝夕心匪懈，活人泽永延。","勖哉慎终始，令名千载传。"]},{"t":"庆寿堂为西溪萧氏赋","f":"五言古诗","c":["西溪构高堂，堂有白发亲。","亲年齐寿考，子孙复诜诜。","大椿枝叶蕃，萱草颜色新。","綵衣拜堂前，旨甘具晨昏。","献寿酌春酒，欢乐及嘉宾。","况逢太平时，至和被八垠。","外无非横加，内无忧患臻。","黄发日优游，庆泽流津津。","作诗歌盛美，庶以垂千春。"]},{"t":"赠郭郎中鼎贞还新淦","f":"五言古诗","c":["客行辞国都，眷言归旧乡。","旧乡渺何许，云山浩茫茫。","我昔当壮年，与子同翱翔。","交谊等金石，志气相激昂。","青云幸际会，喜得同朝行。","睽违屡契阔，南北遥相望。","兹来遘衰疾，乞归何匆忙。","荷蒙圣恩许，感激切中肠。","怅然别我去，执手徒徬徨。","鸿雁鸣索群，我怀增慨慷。","凉飙动萧瑟，川陆悠且长。","及家遂閒适，为乐殊未央。","愿言慎起处，永矣臻寿康。"]},{"t":"为王侍讲时彦题秋意图","f":"五言律诗","c":["长天带远景，绝岛含秋意。","桥响客时过，竹深门独闭。","苍烟迥萧瑟，落日生迢递。","回首大江西，故山何处是。"]},{"t":"题李仕琏山水图","f":"五言律诗","c":["幽岑带烟光，远屿浮岚气。","野水舟自回，山居少人至。","松声度潺湲，云水生迢递。","对此欲忘言，谁能识兹意。"]},{"t":"小景五首为杨少傅东里作 其一 万玉林","f":"五言古诗","c":["瑶林翠如织，玉立何森森。","虚心濯冰雪，直节凌岑崟。","炎暑无六月，清风生满林。"]},{"t":"小景五首为杨少傅东里作 其四 雪景","f":"五言古诗","c":["积雪没深户，溪山绝行迹。","鸟栖迷故林，泉声断馀滴。","中有映书人，宴坐忘朝夕。"]},{"t":"小景五首为杨少傅东里作 其五","f":"五言古诗","c":["青山无垢氛，野水多秋思。","红树带疏烟，夕景生迢递。","客子欲何之，孤舟出村际。"]},{"t":"好学斋为边给事作","f":"五言古诗","c":["伊人慕先哲，积学恒孜孜。","好问不自己，舜尹乃吾师。","於焉烛万理，于以释众疑。","虚心如不足，谦抑恒自持。","力行期远到，贤圣固可希。","勖哉企前轨，庶以慰所思。"]},{"t":"赋存心堂","f":"五言古诗","c":["君子秉恒性，万理备一心。","操存贵弗失，恒恐蟊贼侵。","灵台湛虚寂，天君若监临。","主敬在朝夕，先哲诚所钦。","勖哉崇令德，保此瑶华音。"]},{"t":"朴斋为给事赵文金赋","f":"五言古诗","c":["唐虞世已远，古道迷荆榛。","颓波逝不返，淳风荡无垠。","绮纨尚美䴡，布帛何足珍。","良烹侈玉食，菽粟难并论。","太朴日已散，弥文灭其真。","赵君抱冲素，持守思益敦。","笃行合前轨，秉志期忠纯。","清光迩禁闼，载笔联紫宸。","谠言怀激切，至诚谅斯存。","王风被寰宇，礼乐在弥纶。","永期赞隆治，薄俗斯还淳。"]},{"t":"腊月廿日同陈俊文过武安殡所","f":"五言古诗","c":["尔亡忽两月，我怀独悲伤。","北风号中野，白日惨无光。","抚柩为痛哭，四顾增徬徨。","苍天复苍天，奚忍降暴殃。","垂老失爱子，此恨何时忘。"]},{"t":"帝王膺受天命至圣之德格于天心故三光全而寒暑时群生和而万物育是以上天昭锡景贶以彰盛美钦惟皇上统绍鸿基主宰神人宵旰图治至仁孚于海内至信昭于天下华夷效顺海宇清宁雨旸晦明各顺其叙时和岁登家给人足乃永乐十一年春二月皇上再狩北京行庆赏黜陟之典田野之民莫不鼓舞欢跃瞻仰日月之光华以为盛世太平之贺乃夏五月丁未山东兖州府曹县以驺虞来献白质黑章五采绚烂目光如电尾长倍躯起伏蹲卧不扰不惊在廷臣僚洎蛮夷酋长与夫工商舆?之徒莫","f":"五言古诗","c":["圣皇握乾符，御统膺宝历。","宵衣运神化，日昃弗遑息。","上追虞周治，远迈汉唐迹。","礼乐聿昭宣，人文焕奎壁。","雨旸既顺序，寒暑靡差忒。","闾阎底丰富，男女乐耕织。","洪纤悉包含，物各遂生植。","熙然际时雍，鼓舞歌帝力。","天心屡眷顾，祖考亦昭格。","垂休降纯嘏，咸俾跻寿域。","奇祥粲缤纷，和气寔充塞。","芳甸荐神龟，南郊醴泉溢。","庆云䴡层霄，膏露时委积。","赤麟与紫凤，文采何辉奕。","维兹邹鲁区，神禹所经画。","地灵协坤珍，光气常閟匿。","萃精毓仁兽，于以符至德。","祥飙振丛薄，瑞采动厓壁。","神明为呵护，民庶惊辟易。","二虎从左右，驯狎如服役。","及兹应时至，入献彤墀侧。","猊首而虎躯，黑章而质白。","般般云霞文，粲粲雪霜色。","双瞳夹明镜，紫电光相射。","尾长倍其身，墨花绚胸臆。","初阳发光彩，清冰助标格。","生刍足不践，生物性不食。","俯仰帖不惊，举动甚安适。","回翔荷恩宠，天颜惟咫尺。","率舞同百兽，跄然中仪则。","群臣拜且抃，圣情倍欢怿。","缅思仁兽瑞，旷世斯一获。","周南托佳咏，千古垂简籍。","自从三代降，兹事遂寥寂。","我皇继天位，功烈超古昔。","往年致嘉祥，来献自藩国。","兹晨忽再睹，奇异诚难测。","自非神圣功，上瑞何由得。","我皇乃弗居，诚心愈谦抑。","兢业同禹舜，罔敢怠朝夕。","微臣迩清光，谬沗承明直。","愧乏班马资，献纳鲜裨益。","耿耿怀丹忠，再拜陈悃愊。","皇图万姬周，历年逾八百。","圣寿天地俱，宝祚绵万亿。","作诗谐颂声，庶以播无极。"]},{"t":"送萧知州迪哲赴晋宁","f":"五言古诗","c":["忆昨居頖水，与君同遨游。","昕夕费磋切，讨论极搜求。","我首窃科第，侍从蒙恩优。","君继领高荐，簪笔侍宸旒。","琐闱同出入，交契何绸缪。","忽兹膺宠擢，出守涖名州。","朋从相宴饯，冠盖拥道周。","蹇予托姻好，缱绻难为留。","商飙正袅袅，征旆何悠悠。","南云在万里，道路阻且脩。","居行慎起处，毋为念离忧。","方今际圣明，简贤伫嘉猷。","牧守任抚字，布政先怀柔。","殷勤宣德意，庶用安遐陬。","勖哉慎终誉，永矣扬嘉休。"]},{"t":"题赉溪钓者卷","f":"五言古诗","c":["赉溪有逸士，世本商岩孙。","中岁慕恬适，养晦居丘樊。","垂纶不设饵，志靡耽华鳞。","烟波浩渺渺，鱼鸟恒相亲。","濯缨弄夕影，散发晞朝暾。","企彼渭川穸，洗心欲忘言。","俛仰终宇宙，此乐难具论。"]},{"t":"元夕宴集分韵得坐字","f":"五言古诗","c":["上元弛夜禁，朋游忽相过。","华灯粲中庭，列席邀同坐。","呼酒具殽馔，觞咏更唱和。","繁星入户明，皎月当空堕。","九衢沸箫鼓，杂遝欢声播。","幸此际升平，衰迈惭无那。"]},{"t":"北征晨起即事","f":"五言古诗","c":["客居寡情悰，兀坐不簪缨。","侵晨见箠楚，畏闻哀痛声。","士卒殊饥饱，甘苦亦异情。","盗剽非得已，困迫深可矜。","大将总戎钺，委托任匪轻。","人命在朝夕，胡为死生□。"]},{"t":"送萧深州复任诗","f":"五言古诗","c":["圣皇驭九有，图治如渴饥。","求贤靡不至，实期赞雍熙。","矧兹郡县寄，休戚系黔黎。","简擢苟不慎，易以生怨咨。","深州古名郡，俗尚非昔时。","官守失其政，凋弊日以滋。","公来敷治理，极力为抚绥。","吹嘘振枯朽，扶植苏癃疲。","欣欣沐膏泽，煦煦蒙春辉。","于焉乐生遂，有食且有衣。","徭役既不后，租赋自有期。","豪强遵约束，吏胥惮严威。","黄堂白日静，终岁忘鞭笞。","心清事逾简，弦诵有新诗。","颍川绩可拟，渤海名堪齐。","及兹逾两考，奏最咸称宜。","还官既有命，五马何光辉。","都门一相送，握手暂蹰踟。","春风正骀荡，桃李还芳菲。","酌君光禄酒，尽此黄金卮。","深州日在望，速往毋迟迟。","相期在远大，勿用伤睽离。","候君重来日，三考荣超跻。","努力慎终始，庶以慰遐思。"]},{"t":"素闇为九江贰守魏宗冕赋","f":"五言律诗","c":["素闇有佳士，抱志何休休。","绮丽非所贵，澹泊宁自羞。","返朴存至理，穷源遏奔流。","古道邈难复，努力追前脩。"]},{"t":"六月廿一日立秋偶题","f":"五言律诗","c":["两日风雨过，满目皆秋意。","开轩灏气回，入座凉飙至。","高梧响萧萧，鸣蜩方嘒嘒。","坐念寒暑更，令人发深喟。"]},{"t":"雪窝为翰林修撰苗衷赋","f":"七言古诗","c":["泮池冻压芹藻香，雪窝湛湛通锒潢。","琼姿玉质烱寒素，短棂碧槛凝清光。","蓬莱浩渺彻银阙，罗浮梦里何殊别。","净色微含冷淡风，暗香遥度黄昏月。","当年美人尤好奇，对此转觉心神怡。","花明高阁朝吟处，帘捲寒窗夜映时。","只今远隔西湖侧，欲托幽悰那可得。","青绫儤值玉堂深，梦寐犹疑照颜色。","新图貌得重南金，时来展玩清烦襟。","为君挥翰写长句，愿保平生贞白心。"]},{"t":"题松鸐","f":"七言古诗","c":["薛公画鸐艺殊绝，真迹人间半磨灭。","玉堂退直见新图，毛骨萧疏浑彷佛。","丹砂作顶霜作翎，迥立松梢压苍雪。","试看挺特仙客姿，轩昂岂是樊笼物。","万里高抟辽海风，一声清泪临皋月。","忽然振翼将远举，云薄天空一超越。","肯学池塘鸥鹭群，啄食卑污外空洁。","悬知素壁玩且久，似有凉风起寥泬。","赤松异日许同游，借尔翱翔向金阙。"]},{"t":"上林春雨图为御史罗亨信赋","f":"七言古诗","c":["上林竹深绿如箦，滃然一片潇湘色。","春雨溟濛天际来，净洗琅玕澹空碧。","恍疑白昼鬼神惊，散作碎玉声琮琤。","浓深半隐玄豹色，苍翠低含紫凤翎。","忽然云雾生眼底，似觉阴生带秋意。","乃知画者妙入神，力斡天机有如此。","知君爱竹非寻常，写入图画情难忘。","岁寒节操慎自保，凛凛应同御史霜。"]},{"t":"赠傅子楫德安教授","f":"古风","c":["京师仲冬月，天气寒栗冽。","客怀已无欢，况与故交别。","先君昔教临江时，我亦携书侍讲帷。","春风游泳泮池上，惟君与我最相知。","君心磊落怀奇宝，自分青云致声早。","一从领荐上京华，拜官得似儒官好。","蕲州振铎经几年，广海旋闻席再迁。","栾城契阔三载馀，又闻书考来朝天。","相逢顿觉容发改，却羡当时好风采。","论心但喜别怀舒，话旧犹看故情蔼。","只今南去沐荣恩，尽道德安风俗淳。","朝回相送情匆匆，作诗聊以申殷勤。","征车轧轧金台路，落日风沙渺烟树。","人生聚散胡尔为，况乃相看各迟暮。","君行远道勿蹉跎，正值岁寒霜雪多。","德安早到如相忆，莫道衡阳无雁过。"]},{"t":"赠贡士王志浩赴东莞训导","f":"七言古诗","c":["东风三月莺乱啼，都门冠盖相追随。","乡人故旧领除命，布衣一日生光辉。","王郎素非寻常者，浩气凌霄绝潇洒。","昔年充贡登成均，万里青云重光价。","已看蟾宫擢高枝，复闻战艺来春闱。","霜蹄暂蹶未为失，一官雅称克儒师。","番禺南望渺何许，便道还能过乡土。","梅雨连村旅舍昏，林阴满地邮亭午。","悬知到日夏方深，杏坛昼永分清阴。","皋比日宴说经史，座间济济皆青衿。","况当圣治文明日，宵旰孜孜在儒术。","兹行仰体圣明心，作育群才须努力。","朝回送别惜匆忙，且尽花前酒一觞。","岭南若遇回京使，犹待椷书寄玉堂。"]},{"t":"次少师姚广孝禁体雪诗韵","f":"七言古诗","c":["江空岁晏天作雪，滕六先驱势逾裂。","同云惨淡始异色，眼底纷纭忽惊瞥。","山川高下渐堆积，东西岐路那分截。","晨光炫烂隐乌彩，夕景微茫封蚁垤。","上林千树夐相宜，九重双阙何殊别。","金河水浅凝不流，玉碗无声冻先结。","满城泥滑马蹄深，空院香清鸟声绝。","不闻窗外林叶声，时听阶头竹枝折。","联翩乱洒入衣袖，宛转斜窥投隙穴。","拂槛穿云去复来，随风带雨吹还灭。","书生把卷惬清妍，红女停针愁凛冽。","貂裘翠被未觉温，火井汤泉那复热。","棹回剡曲发佳兴，词传郢客停歌舌。","淮阴破敌誇神速，渤海思家叹骚屑。","知公素有冰蘖声，岁寒不变青松节。","梁园赋就笔屡呵，石鼎新烹水微咽。","腊前预喜兆丰年，潜祛螟螣消馀孽。","阴阳顺序民物和，昭锡异瑞天心悦。","嗟予才薄惭蹇塞，十年载笔词臣列。","捐躯报国誓匪他，长秉忠诚心似铁。","朝回看雪天上来，属和长歌资一吷。"]},{"t":"重午日侍从内苑观击毬射柳应制","f":"七言古诗","c":["大明丽天圣人作，弘宣治化昭礼乐。","华夷向风四海清，人和岁丰物咸若。","翠华五载重巡幸，经营北都同卜洛。","惟时帝京值重午，习武驰毬戒程约。","霓旌凤盖天边来，禁苑清晨张御幄。","腾腾虎士尽貔貅，剑戟相摩耀锋锷。","毬门结束正当中，两朋左右杂相角。","玉花骢马络青丝，锦衣绣服相煇烁。","吹箫伐鼓杂鸣笳，马前奋击争挥霍。","星飞电掣合变化，神珠宛转当空落。","翻身奋臂挽雕弓，白羽交飞向寥廓。","穿杨百步巧难工，分筹得隽咸惊愕。","至尊有喜动颜色，御前敕赐恩尤渥。","侍臣载笔预簪花，宫壶赐饮黄金爵。","酒酣献寿效嵩呼，倾竭丹诚比葵藿。","作诗再拜进蓬莱，欲拟长杨惭谫薄。","神功圣德不可名，万岁千秋等乔岳。"]},{"t":"张孝子歌为尚宝司丞张信赋","f":"七言古诗","c":["我闻山东张孝子，早岁衔哀报严父。","昊天罔极恩莫酬，教育维持赖慈母。","母年未艾孝弥敦，奉盈执玉心所存。","鸡鸣问寝候堂前，婉容愉色如春温。","綵衣娱侍供调膳，从容食饮频相劝。","每怀鹤发未成霜，筋力愈强身愈健。","三春慈竹阴满堂，萱草含绿凌冰霜。","板舆缓挽向东风，穿竹看花清昼长。","花前酌酒仍高歌，寿觞迭进慈颜和。","子孙满前母更寿，此乐人间真不多。","朅来孝亲名誉起，奉檄作官亲更喜。","紫诰回鸾下五云，诏书褒锡光闾里。","九重亲切掌帝符，日趍琐闼鸣佩琚。","况闻伯兄更脱略，十年执戟侪金吾。","近者受命殄贼曹，南征万里清海涛。","弟兄忠孝有如此，一心只欲愉勤劳。","古来事君违所亲，事亲宁复能忠君。","子今际遇事明主，得禄奉亲逾古人。","嗟哉孝子不易得，勖子终养崇明德。","何时升堂为母寿，更作长歌写胸臆。"]},{"t":"为杨庶子题纸屏画竹","f":"七言古诗","c":["我昔隐居在山谷，绕舍只令种脩竹。","清风白昼洒苍雪，终日吟哦看不足。","一从携书来北阙，遂与此君成久别。","平安十载知何似，往往思之心欲折。","杨君亦是爱竹者，官舍新成最幽雅。","纸屏拂拭无点尘，满写琅玕更潇洒。","昨来置酒邀客子，灯前见之惊且喜。","停杯借问作者谁，似与老可同高致。","墨花淋漓真可爱，黯淡犹疑鬼神会。","初看积翠落檐端，便觉湍声起窗外。","数竿隔水各千尺，微露青林带秋色。","暮雨寒霏紫凤翎，惊涛瞑卷苍龙翼。","知君好竹幽思殊，朝回看画仍读书。","临风或吹苍玉管，对月时弄青珊瑚。","嗟哉此君贞且良，丰姿凛凛非寻常。","世情高下逐冷暖，此君志节无炎凉。","冰霜岁晏慎自保，相期白首毋相忘。"]},{"t":"洪厓山房歌为祭酒胡公作","f":"七言古诗","c":["我闻洪厓山水好，往往思之不能到。","今君却忆洪厓山，欲结茅庐傍幽岛。","画图点染写深思，数来邀我题新诗。","展图试觅幽栖处，洪厓千仞凌空垂。","洞口寒云杳莫分，石桥流水长潺湲。","閒来或有渔樵到，尽日那闻鸡犬喧。","丹霞碧树连幽嶂，翠壁青林更萧爽。","落花啼鸟自四时，芝草琅玕日应长。","君家玉峡我故乡，几年卜居来豫章。","城中地窄少耕种，唯有图书堆满床。","忆昨射策辞乡县，承恩数上黄金殿。","玉堂视草袖天香，花里迎銮侍清宴。","朅来扈从金台北，载笔还为两京客。","渐觉奔驰筋力衰，才过五十头俱白。","西山峨峨江水深，怅望洪厓违宿心。","咏归未有陶潜赋，招隐空怀桂树吟。","嗟我平生慕幽雅，亦欲移居玉山下。","苍松翠竹不用栽，石田野圃宁须借。","几时诏许乞身閒，共脱朝簪寻故山。","预约洪厓结茅屋，江上扁舟相往还。"]},{"t":"为勉仁学士题王孟端所画松桧图","f":"七言古诗","c":["长松参天苔藓碧，飞泉迸落苍厓石。","雾雨三秋入杳冥，风林六月含萧索。","伊谁妙笔与神通，力斡造化千钧雄。","此材卓荦为世用，老大犹当备梁栋。","老桧苍苍拥高盖，交柯崛起蛟龙背。","悬厓惨淡雷雨生，白日苍茫鬼神会。","朝回坐对太古姿，凛然不受霜雪欺。","为君歌罢久叹息，要知画好如此诗。"]},{"t":"徽庙古松山鹊为顾进士作","f":"七言古诗","c":["松梢盘拿出岩壑，一夕山风吹子落。","几回度涧听松声，横枝忽见飞来鹊。","翠衿红觜一何奇，误疑青鸟降瑶池。","根深茯苓不易斸，王母羽盖今何之。","宣和宫中迹如扫，胡沙漠汉天地老。","莫向松间占鹊声，五国城荒长芳草。"]},{"t":"大若灵根为医者顾东启作","f":"七言古诗","c":["吾闻永嘉朱孺子，幼慕玄真王道士。","鍊药冥栖大若岩，日服丹砂学冲举。","时从绝岭斸黄精，饵之十年道不成。","偶来溪边见二犬，奇形异状忽心惊。","追踪逐影何恍惚，枸杞根深下盘屈。","乃知此物鲜通灵，采食应能致仙术。","斩根净洗清溪流，宝鼎温温瑞气浮。","煮来三夕火不绝，味若崖蜜倾金瓯。","孺子饮之惊且悟，便觉胸怀洒甘露。","清风两腋肌骨轻，白日飞腾入云去。","玄真引领慕升仙，西陶山中自长年。","山人往往寻踪迹，出没隐显随风烟。","君家业医今几世，活人功多人感惠。","何用当年枸杞根，满林红杏皆春意。"]},{"t":"送太守卢玉润还新淦展墓","f":"七言古诗","c":["蓟门十月多北风，道上垂杨枝已空。","离筵呼酒劝行客，酒杯有尽情无穷。","卢君自是同乡里，况复青云托知己。","选部曾推藻鉴明，朝端共说才华美。","一朝承擢守钱塘，朱幡皂盖生辉光。","布宣德化耐繁剧，抚字黎庶多慈良。","是邦从昔称难治，闾井欣欣乐君至。","数邑豪奢自敛踪，海滨赤子无遗利。","政成九载复朝天，喜得论心向日边。","九重奏绩策书最，万里承恩暂赋还。","匆匆话别临长道，昨日红颜总衰老。","风前雁影去人遥，马上狐裘觉寒早。","南上归舟莫太迟，梅开定是到家时。","乡中故旧欢迎处，应叹昔游今若斯。","归荣昼锦诚堪羡，桑梓情深难久恋。","明年八月候趍朝，五云深处重相见。"]},{"t":"瑞兔","f":"七言古诗","c":["圣皇一德膺天命，省方巡守因时令。","维兹灵兔表瑞徵，一色玄肤如玉瑩。","毫端纯洁明且净，回身滃若玄云凝。","目光点漆微开镜，黑毳毵毵烱相映。","锋棱矫矫塞逾劲，意气直与秋空迥。","适当玄冥司斗方，乃有此兔色纯正。","贡来玉阶朝万乘，百辟抃舞欢呼竞。","抚摩驯扰有异性，白麟朱雁安足胜。","奇哉此兔遭荣幸，沐浴膏泽为灵应。","瑶圃嬉游谁与并，小臣拜睹形歌咏，万岁千秋颂神圣。"]},{"t":"瑞应甘露诗","f":"七言古诗","c":["圣皇御宇四海清，际天极地俱来庭。","诞敷德教及遐迩，重熙景运昭文明。","九重端拱成至治，恩泽汪洋悉沾被。","至和薰蒸盈两间，上瑞奇祥日相继。","永乐已亥维仲冬，天乳明润当太空。","孝陵峨峨霄汉上，甘露又降松柏中。","弥柯布叶总醲郁，绚彩流光满山谷。","遥看宛若缀蠙蛛，近睹犹如屑琼玉。","千林万树动晴辉，天风吹香袭人衣。","絪缊本是和气结，璀璨不逐朝阳晞。","数日霏微亘朝夕，湛湛瀼瀼厚愈积。","天酒空闻自古传，神浆始向今时得。","臣民庆抃传京师，东宫采撷心更怡。","玉壶盛取献天子，囊以文锦登丹墀。","金门洞开赡黼扆，龙颜悦怿称绝美。","当殿传宣赐近臣，满朝动色怀深喜。","须臾分赐遍得尝，全觉饴饧难比方。","岂犹心神益清爽，顿使疲薾臻平康。","臣闻桢祥不易致，萃美凝英逢盛世。","圣德巍巍治道隆，灵贶骈蕃出天意。","庆云焕耀映皇都，寿星夜粲天南隅。","瑞光郁郁成五色，弥满宫城绕帝居。","嘉禾瑞麦纷薿薿，麒麟驺虞灵囿里。","京树乌翔色似霜，仙井泉流甘若醴。","还看玉兔贡紫宸，毛质漆黑诚可珍。","煌煌瑞牒难备录，又见甘露来兹辰。","皇心乾乾尚谦抑，德配轩尧与天一。","上帝景命重眷顾，太祖神灵永昭格。","小臣拜进甘露篇，嵩呼蹈舞玉阶前。","皇图圣寿同天地，陛下鸿名万古传。"]},{"t":"长角兽歌","f":"古风","c":["圣人端拱御八方，车书混一超虞唐。","仁恩义泽霈洋溢，雨旸时序民物康。","南极炎荒北穷发，西逾月窟东扶桑。","陆詟水慄悉稽颡，辇琛奉贽来梯航。","维时天心眷皇德，纷纷总总来奇祥。","麟虞在郊凤在薮，白乌驯雉参回翔。","醴泉出地甘露降，嘉禾瑞麦何穰穰。","前年西域贡狮子，赤豹神鹿纷成行。","今年海外见奇兽，殊姿异状尤非常。","茸茸紫毳瑩苍璧，两角棱棱三尺强。","非兕非豸亦非鹿，玄云蓊郁凝天章。","双瞳夹镜黑如漆，四足捷疾行跄跄。","徵图考牒不可辨，载稽博物何茫茫。","远人效贡儗珍异，径涉大海扬飞樯。","荐之雕笼藉芳褥，再拜奉献登明堂。","是时九重启阊阖，旭日照耀森开张。","祥飙瑞霭相拂掠，佳气郁勃欢声扬。","乃知圣德极广远，覃及庶类蒙恩光。","岂知此兽更奇绝，性质驯雅胜白狼。","玄犀角耑未堪儗，九真所献那足方。","虞廷率舞先百兽，上协箫韶仪凤凰。","太平幸际千载会，愿纪鸿绩镌琳琅。","陈词稽首歌圣德，天子万寿地久同天长。"]},{"t":"福禄兽歌","f":"七言古诗","c":["有兽有兽名福禄，逸态奇姿异凡畜。","身高五尺力如虎，一日千里超骥足。","奇文间错分黑白，毛质无瑕瑩如玉。","目光瞳眬夹明镜，掩映玄云散朝旭。","纷纷缟毳雪花寒，皓彩瑶光何炜煜。","超腾迥觉长风生，一鸣解使百兽服。","海南之国卜刺哇，乃有此兽出大麓。","虞人致之匪羁绁，弗迫弗驱自驯伏。","万里飞航度海来，天吴海若相参逐。","山川处处流光彩，祥烟瑞霭飘芬馥。","清晨导引献九重，从以玄犀与神鹿。","乃知圣德被广远，航海梯山日相属。","远人稽首贡方物，异瑞奇祥莫殚录。","驺虞麒麟在灵囿，渥洼龙媒聚天育。","愿将职贡写成图，一统华夷集诸福。","吾皇万寿与天齐，圣德神功昭简牍。"]},{"t":"为礼部金尚书纯梅花图","f":"七言古诗","c":["尚书示我梅花图，雪色一片涵冰壶。","岁寒萧索少俦侣，偃蹇颇觉形容癯。","南枝一夜回枯槁，漏泄人间春信早。","才看冷蕊耀晨辉，又见繁花照晴昊。","罗浮山人无俗尘，参横月落长相亲。","仙姿缥缈出姑射，白玉为质冰为神。","水边篱落幽深处，梨云半掩瑶台树。","纸帐虚明素影分，银屏皎洁寒香度。","向来孤山风物清，千葩万干何纵横。","林逋几度惬幽赏，长吟屡遣花神惊。","只今零落无知己，惟是西湖渺烟水。","回首当年放鹤亭，千古清风孰能拟。","尚书爱此图画工，标格直与梅花同。","正当鼎鼐调元日，愿报吾皇恩眷隆。"]},{"t":"狮子歌","f":"古风","c":["圣皇御天弘庙略，敷宣鸿化昭礼乐。","登庸俊贤亲简擢，河清海晏雨旸若。","民物熙熙遂耕凿，奇祥异瑞叠昭灼。","朝野颂声相继作，封疆视古益恢拓。","幅?相距何寥廓，东穷扶桑南海角。","西涉流沙北荒漠，山梯海航日联络。","玉帛筐篚纷交错，侏?椎卉相唯诺。","奔走贡献填郊郭，金天之西路绵邈。","粤有神兽匿深壑，非熊非罴亦非駮。","咆哮一声震崖㟧，曰为狮子何卓荦。","百兽见之遁且却，象犀虎豹狸与貉。","伏地脑裂俟其玃，西人致之脱羁缚。","载之雕阑覆以幄，雄风长云相拂掠。","远逾流沙度河朔，黄金台前霜正落。","五云辉辉映楼阁，觚棱晓月明金爵。","阊阖九重方启钥，远人致词甚敦朴。","薄贡远物效勤悫，毛为黄茸光濯濯。","两目晶荧惊电烁，铜头铁䈥纷荦确。","奋髯吐舌耸龈腭，尾大如斗何挥霍。","轩然猛气如欲搏，左顾右盻喜而跃。","衣袂日月荣恩渥，疏涤雨露远氛浊。","饱食紫芝谢丛薄，瑶圃琼林以为托。","乃知圣皇德至博，同仁一视靡厚薄。","声教所暨如橐籥，指挥万国在掌握。","威服强梗慑暴恶，迩安远怀遵约束。","神功巍峨等山岳，小臣献诗愧雕琢，万岁千秋歌永乐。"]},{"t":"拜和圣制元夕观灯诗","f":"七言古诗","c":["天眷皇明基祚隆，肇建两京壮且雄。","龙楼凤阁倚天表，飞甍杰构凌层空。","鸿图巩固地同厚，宝历绵久天与崇。","祥云耀采析木上，佳气遥接扶桑东。","西山千仞列屏幛，河流九曲如朝宗。","连城回抱负沧海，重关巀嵲临居庸。","九重冠盖自济济，五城钟鼓何沨沨。","恢弘盛烈莫伦拟，绵延庆泽无终穷。","万机图治意尤切，奉天勤民心愈忡。","群生熙洽际文治，万国清宁昭武功。","风调雨顺乐生遂，潜消疾疠无疚恫。","是时玉京值元夕，阳和应候回春融。","六鳌戴山来海上，千仞突兀摩苍穹。","金吾奉敕㢮夜禁，太平乐与华夷同。","銮舆乍临丹阙外，璧月正照青天中。","綵楼深护芙蓉暖，瑶波荡漾金莲红。","祥烟细绕笙歌队，天香时度罗绮丛。","赏心乐事固不偶，良辰美景真难逢。","小臣感激荷恩宠，拳拳补报怀摅忠。","仰瞻宸翰焕奎壁，妙参造化天同工。","都俞赓歌继虞舜，垂衣致治侪轩农。","敛时锡福集灵贶，坐令寰宇歌年丰。","愿期圣寿齐天地，万年永乐同熙雍。"]},{"t":"秋日登万岁山","f":"古风","c":["万岁之山高插天，远摩苍翠凌紫烟，琼楼玉树何娟娟。","莺啼白昼出深谷，缟鹤岁久巢松巅。","洞门阴阴苔藓碧，石涧九曲通流泉。","日转金舆经翠巘，风回仙伏度花前。","天香遥散广寒外，紫翠近落瑶池边。","方壶员峤果安在，阆风瑶圃徒虚传。","偶来登览上绝顶，便欲振袂凌飞仙。","凌飞仙，坐阅天地长不老，上下日月同周旋。"]},{"t":"分韵得西山晴云送萧郎中伯辰之官南京","f":"七言古诗","c":["西山嵯峨插天半，长日晴云散空外。","霏霏郁郁烂成文，兀兀童童列车盖。","纷纷五彩发青红，流丹曳紫辉层空。","朝连翠霭绚初日，暮带浮岚逐断风。","深州太守最潇洒，十载看云爱幽雅。","昨来拜命尚书郎，振袂忽辞双阙下。","平生忠孝廉且勤，聚散寻常宁足论。","从龙早已应嘉运，为霖尚想摅经纶。","西山回首日渐远，还望飞云重留恋。","南宫更喜对钟山，看云坐忆题诗遍。"]},{"t":"何将军山林图诗","f":"七言古诗","c":["寰中山林无处无，奚独将军名最都。","不因工部有佳句，后人那得知其故。","金川玉峡秀且奇，潭溪更在金川西。","将军奕世远孙子，继承文采尤光辉。","名园绿水南塘麓，第五桥边富脩竹。","真宰何年驱六丁，掇取灵区过潭曲。","石栏点笔听流莺，银甲金鱼旧日情。","四时佳致宛犹昨，一段胜景真天成。","何郎意度尤潇洒，貌取山林入图画。","朝来访我欢相持，索我题诗说乡社。","临风濡毫为写之，却忆故山劳梦思。","濠梁谷口未应远，白云流水还相期。","明当乞假向天子，锦衣快着归乡里。","预拟山林作胜游，马蹄踏遍烟霞里。"]},{"t":"奉和学士胡公春日陪驾同游万岁山 其二","f":"五言律诗","c":["磴道高低出，烟霞远近分。","雕阑凌绝壁，丹户倚层云。","古木含苍翠，灵芝毓秀芬。","仙山应未远，不使世人闻。"]},{"t":"奉和学士胡公春日陪驾同游万岁山 其三","f":"五言律诗","c":["紫殿青霄外，何年结构奇。","攀缘疑失路，回合讶多岐。","竹露凝蛛网，松烟湿兔丝。","经行随处好，尽日不知疲。"]},{"t":"奉和学士胡公春日陪驾同游万岁山 其四","f":"五言律诗","c":["萦纡缘岛树，迤逦傍林花。","举目疑天近，回头觉路赊。","追趍穷物色，幽赏惜韶华。","小立迎鸾驭，中官拟进茶。"]},{"t":"奉和学士胡公春日陪驾同游万岁山 其五","f":"五言律诗","c":["玉辇千官从，晴波太液春。","光风先解冻，淑景更宜人。","泛月思仙艇，看鱼忆钓纶。","宸游恩渥重，何以报尧仁。"]},{"t":"奉和学士胡公春日陪驾同游万岁山 其六","f":"五言律诗","c":["巀嵲凌丹阙，迢遥跨紫台。","龙香浮日动，凤盖拂云来。","叠巘参差出，层崖隐映开。","幽寻不可极，临眺重徘徊。"]},{"t":"奉和学士胡公春日陪驾同游万岁山 其七","f":"五言律诗","c":["始从京国至，复向广寒游。","琪树花争发，瑶岑翠欲流。","丹丘千岁在，紫涧四时幽。","缥缈闻仙乐，随风到殿头。"]},{"t":"奉和学士胡公春日陪驾同游万岁山 其九","f":"五言律诗","c":["仙台金露静，画栋玉虹高。","日月回三岛，乾坤奠六鳌。","碧瓯传细茗，银瓮出香醪。","千载恩荣重，追攀不惮劳。"]},{"t":"奉和学士胡公春日陪驾同游万岁山 其十","f":"五言律诗","c":["侍宴分瑶席，莺花照绮罗。","中官催赐酒，光禄为笼鹅。","汉业千秋盛，尧年万寿多。","愿言歌圣德，勒石照岩阿。"]},{"t":"秋日随驾出安定门偶成","f":"五言律诗","c":["西风初退暑，白苧已生凉。","水郭稻花晚，林塘荷芰香。","雁声逾塞急，燕子去巢忙。","落日金台外，萧条客思长。"]},{"t":"冬日早朝口号","f":"五言律诗","c":["紫陌趍朝早，挥鞭信马蹄。","水声桥上下，人语市东西。","拂帽霜华重，垂天斗柄低。","九门看欲曙，先听乳乌啼。"]},{"t":"冬夜独坐","f":"五言律诗","c":["寒灯照孤馆，独夜思悠悠。","久客谁青眼，慈亲今白头。","疏钟度双阙，长篴起高楼。","遥念小儿子，娇痴不解愁。"]},{"t":"腊月二十四夕偶成 其一","f":"五言律诗","c":["岁事只如此，匆匆又小年。","兰灯看独照，柏酒已先传。","月隐金台雪，香霏禁树烟。","故园今万里，南北寸心悬。"]},{"t":"腊月二十四夕偶成 其二","f":"五言律诗","c":["浮生若萍梗，岁月易蹉跎。","久客乡书少，慈亲白发多。","春回残雪在，腊尽小年过。","未就閒居赋，聊吟桂树歌。"]},{"t":"玉堂晚出","f":"五言律诗","c":["玉堂初罢直，缓步散鸣珂。","城阙日将暮，河桥风更多。","岁华渐摇落，人事易蹉跎。","未有田园计，谋生将柰何。"]},{"t":"次邹侍讲夜坐即事","f":"五言律诗","c":["掩卷坐清宵，围炉拥敝貂。","捲帘寒易入，汲水冻难消。","人静传疏漏，庭虚度急飙。","夜阑传北斗，天路正逍遥。"]},{"t":"除夕次韵","f":"五言律诗","c":["宦游逾十载，长以客为家。","腊酒轻浮蚁，兰缸细吐花。","寸心倾北阙，数口隔京华。","明日逢新岁，春光遍海涯。"]},{"t":"挽秀才黄卓母","f":"五言律诗","c":["忽听传凶问，慈亲隔九原。","凄凉万里恨，未报百年恩。","客路经寒雪，云山望故园。","临岐一相送，悲恸不堪闻。"]},{"t":"追和学士胡公秋日同陪驾重游太液池 其一","f":"五言律诗","c":["太液临仙岛，微凉动早秋。","雨馀芳树静，岸远杂花稠。","鱼跃冲波外，鸥眠近水头。","词臣叨宠渥，载笔重追游。"]},{"t":"追和学士胡公秋日同陪驾重游太液池 其二","f":"五言律诗","c":["瑶波通碧海，琼岛倚天中。","鸟度红莲雨，莺啼细柳风。","泉香流石砌，树暗隐仙宫。","尽日都忘倦，登临兴未穷。"]},{"t":"追和学士胡公秋日同陪驾重游太液池 其三","f":"五言律诗","c":["树窈回仙径，花深映石床。","云光连岛静，水气入衣凉。","御手分冰果，天厨送玉浆。","吾皇千万寿，流泽更汪洋。"]},{"t":"追和学士胡公秋日同陪驾重游太液池 其四","f":"五言律诗","c":["远水含秋色，飞霞映晚天。","折荷惊白鹭，倚树听玄蝉。","翠合三山近，波涵一镜圆。","子云才更好，独步赋甘泉。"]},{"t":"追和学士胡公秋日同陪驾重游太液池 其五","f":"五言律诗","c":["辇路通瑶岛，天河跨玉津。","凉风生细浪，疏雨浥香尘。","碧草穿沙短，红菱出水新。","宸游多乐事，侍从忝词人。"]},{"t":"追和学士胡公秋日同陪驾重游太液池 其六","f":"五言律诗","c":["驰道平如掌，金舆向日移。","画桥低树影，粉槛压花枝。","展席鸥相近，回鞭鹤未知。","故人诗句好，尽得写清奇。"]},{"t":"追和学士胡公秋日同陪驾重游太液池 其七","f":"五言律诗","c":["高阁青霄外，平台落照间。","未须论弱水，即此是仙山。","禁树祥乌集，琼林白鹤还。","经行多异趣，景物自幽閒。"]},{"t":"追和学士胡公秋日同陪驾重游太液池 其八","f":"五言律诗","c":["内苑消残暑，满池开藕花。","凉烟生薜荔，落日映蒹葭。","凤盖随丹辇，鸾笙载玉车。","西山浑咫尺，紫气接飞霞。"]},{"t":"追和学士胡公秋日同陪驾重游太液池 其九","f":"五言律诗","c":["綵仗临花屿，仙舆隔画阑。","敲冰分学士，供膳促中官。","屡得陪清赏，重来喜遍观。","微生遭盛际，霈泽海同宽。"]},{"t":"追和学士胡公秋日同陪驾重游太液池 其十","f":"五言律诗","c":["日下龙光近，花间辇道开。","旗翻池影动，香逐好风来。","赋诧相如好，诗论太白才。","胜游偏称意，欲往更迟回。"]},{"t":"郭氏遗安堂","f":"五言律诗","c":["世系出汾阳，高门弈叶芳。","诗书存道义，耕稼乐时康。","盛德贻谋远，传家积庆长。","安危有明鉴，垂训在兹堂。"]},{"t":"试院偶成柬诸同志","f":"五言律诗","c":["圣主崇文治，南宫较艺时。","贤才应有待，藻鉴岂容私。","日傍炉烟转，春随刻漏移。","自惭叨笔砚，饱食更何裨。"]},{"t":"院中雨寒夜坐","f":"五言律诗","c":["入院多风雨，清宵独掩扉。","灯寒难把卷，坐久欲添衣。","人语喧江市，鸦栖避棘闱。","贤才今独盛，吾道有光辉。"]},{"t":"花晨纪怀","f":"五言律诗","c":["锁院春过半，趍朝敢后期。","捲帘晨起早，看卷夜眠迟。","战艺俱争捷，抡才属有为。","胪传黄榜动，春满凤凰池。"]},{"t":"二月廿五日夜写进士榜复命","f":"五言律诗","c":["花隐兰灯夜，香浮虎榜春。","飞腾瞻日月，感会在风云。","匡坐听寒漏，鸣珂候紫宸。","长安闻揭晓，尽夕有行人。"]},{"t":"赠许子谟博士还北京胄监","f":"五言律诗","c":["南宫初上考，拜命即言还。","淮树云连海，燕台雪满山。","交游十载旧，淹滞一官閒。","愧我叨恩宠，空怜两鬓班。"]},{"t":"冬日扈驾猎龙山同尚书蹇公学士胡公登斗首山佛窟寺偶成十诗奉简 其一","f":"五言律诗","c":["梵刹倚崔嵬，登临此日来。","穿林缘翠巘，坐石拂苍苔。","绝壁浮图在，空岩佛窟开。","凭高一回首，佳气满蓬莱。"]},{"t":"冬日扈驾猎龙山同尚书蹇公学士胡公登斗首山佛窟寺偶成十诗奉简 其二","f":"五言律诗","c":["侍从朝初罢，乘閒散马蹄。","黄麾云外见，猎骑望中迷。","石室疑龙卧，禅床听鹤栖。","经行有佳兴，且复记新题。"]},{"t":"冬日扈驾猎龙山同尚书蹇公学士胡公登斗首山佛窟寺偶成十诗奉简 其三","f":"五言律诗","c":["日晏疲登顿，遥峰入望微。","云根孤犬吠，林外一僧归。","霜滑犹沾屐，苔深欲染衣。","底须论说法，到此已忘机。"]},{"t":"冬日扈驾猎龙山同尚书蹇公学士胡公登斗首山佛窟寺偶成十诗奉简 其四","f":"五言律诗","c":["空寂浑无事，从来远俗氛。","崖深留冻雪，松老驻寒云。","碧殿香烟静，层云紫翠分。","下方尘扰扰，钟磬有谁闻。"]},{"t":"冬日扈驾猎龙山同尚书蹇公学士胡公登斗首山佛窟寺偶成十诗奉简 其五","f":"五言律诗","c":["野旷澹朝晖，山光拂翠微。","青松低石屋，黄叶碍柴扉。","长日僧閒卧，终年客到稀。","自缘尘俗少，甘与世人违。"]},{"t":"冬日扈驾猎龙山同尚书蹇公学士胡公登斗首山佛窟寺偶成十诗奉简 其六","f":"五言律诗","c":["江山如画里，满目尽乾坤。","翠拂旌旗动，风吹鼓歌喧。","晴烟分野色，旭景散春温。","喜有同袍在，幽期可共论。"]},{"t":"冬日扈驾猎龙山同尚书蹇公学士胡公登斗首山佛窟寺偶成十诗奉简 其七","f":"五言律诗","c":["名山不易到，欲去重盘桓。","浩荡添诗兴，行吟驻马鞍。","风泉杂钟梵，岚翠湿衣冠。","顿此忘尘幻，偏令眼界宽。"]},{"t":"冬日扈驾猎龙山同尚书蹇公学士胡公登斗首山佛窟寺偶成十诗奉简 其八","f":"五言律诗","c":["古木含馀霭，垂萝隔紫烟。","碑残尚没草，井废尚通泉。","梵钵留深殿，天花雨法筵。","山僧少迎送，高卧不知年。"]},{"t":"冬日扈驾猎龙山同尚书蹇公学士胡公登斗首山佛窟寺偶成十诗奉简 其九","f":"五言律诗","c":["偶寻方外去，佳兴亦悠哉。","云气随冠冕，花香拂酒杯。","閒时难再得，何日更重来。","向晚銮舆动，争随骑从回。"]},{"t":"冬日扈驾猎龙山同尚书蹇公学士胡公登斗首山佛窟寺偶成十诗奉简 其十","f":"五言律诗","c":["未有人知处，经行到上方。","丹霞浮御气，宝树散天香。","碧嶂猿啼静，遥空雁影长。","题诗寄行迹，回首意难忘。"]},{"t":"赠陈绍夔胡季南下第再试归南京胄监","f":"五言律诗","c":["领荐来京国，青云竟未逢。","圣情尤轸念，召试独从容。","夜雨辞金殿，春风过辟雍。","他年期射策，须敌万夫雄。"]},{"t":"端午赐宴观击毬射柳 其一","f":"五言律诗","c":["端午恩荣重，宫筵进寿觞。","赐来银扇好，分出綵丝长。","角黍金盘荐，菖蒲玉瓮香。","赋诗惭倚马，再拜献君王。"]},{"t":"端午赐宴观击毬射柳 其二","f":"五言律诗","c":["凤辇乘时动，宁辞阅武勤。","柳间千骑合，花外两朋分。","羽箭凌飞电，金毬度綵云。","年年端午节，荣遇沭深恩。"]},{"t":"端午赐宴观击毬射柳 其三","f":"五言律诗","c":["千官随鹤驭，冠盖拂云来。","日转旌旗重，风清鼓角催。","玉骢低柳过，綵仗逐花回。","献赋长杨里，还称万寿杯。"]},{"t":"端午赐宴观击毬射柳 其四","f":"五言律诗","c":["仙伏丹霄外，銮舆禁苑东。","转丸驰宝马，拂羽试雕弓。","得綵欢声合，分筹宠赉浓。","太平无以报，献纳愧扬雄。"]},{"t":"赠友人廖自勤王恪赴交趾 其一","f":"五言律诗","c":["万里南交路，君今作远游。","着鞭临祖道，受诏出皇州。","汉柱云烟古，秦林瘴疠收。","幕中如有问，珍重为参谋。"]},{"t":"赠友人廖自勤王恪赴交趾 其二","f":"五言律诗","c":["慷慨属櫜鞬，离筵惜解分。","班超志投笔，司马独能文。","虎旅连云动，笳声向月闻。","安边有良策，及此树功勋。"]},{"t":"春日随驾出却世偶过田家 其一","f":"五言律诗","c":["东风被原野，草木亦滋荣。","脉脉泉流响，喈喈时鸟鸣。","老翁扶杖出，稚子把犁耕。","民俗安浮朴，熙然乐太平。"]},{"t":"春日随驾出却世偶过田家 其二","f":"五言律诗","c":["遥峰落平野，小径入柴扉。","雨后桑麻长，春深牛犊肥。","林花轻拂帽，空翠近沾衣。","惆怅蘼芜绿，天涯殊未归。"]},{"t":"杏园春晚图为李士文赋","f":"五言律诗","c":["种来看渐满，千树已成林。","向晓云霞重，方春雨露深。","闭门容虎卧，把卷听莺吟。","结实长收谷，谁知植德心。"]},{"t":"随驾出拜郊过平坡寺","f":"五言律诗","c":["远上平坡寺，山行似七盘。","到门卸鞍马，坐石解衣冠。","仙井龙曾化，僧房犬自看。","乘舆瞻已远，万骑拥旌竿。"]},{"t":"元夕午门赐观灯 其一","f":"五言律诗","c":["新岁逢元夕，看灯紫禁来。","云间仙伏出，花里绣筵开。","月转双龙阙，春浮万寿杯。","传柑当此日，献颂愧非才。"]},{"t":"元夕午门赐观灯 其四","f":"五言律诗","c":["驰道开仙跸，中天建羽旄。","星连三岛近，仗立五云高。","凤吹迎仙乐，龙香荐玉醪。","九重恩似海，春色上宫袍。"]},{"t":"元夕午门赐观灯 其五","f":"五言律诗","c":["鹤驭云中下，仙人海上回。","星桥连阁道，绛蜡炫蓬莱。","民物同遭遇，衣冠得重陪。","酣歌称万寿，更上紫霞杯。"]},{"t":"为方尚书宾题山水图","f":"五言律诗","c":["翠崦参差合，疏林隐映开。","白云生野水，树色掩楼台。","钓艇烟中去，菱歌江上来。","山阴未可到，贺监几时回。"]},{"t":"为序复来求题","f":"五言律诗","c":["异种穹窿产，移栽自昔年。","发生宜土壤，润泽近山泉。","品出武夷外，香分谷雨前。","谁能识滋味，为问赵州禅。"]},{"t":"寄长洲周广文","f":"五言律诗","c":["风雪大如许，怀人将柰何。","春归双鬓老，腊尽一年过。","泮水菁莪意，淮南桂树歌。","玉堂叨笔砚，感激受恩多。"]},{"t":"赠友人赴亳县","f":"五言律诗","c":["一官赴亳县，九月发金台。","雪色侵行李，梅花照酒杯。","廉平需岂弟，抚字赖贤才。","迢迤关河意，相思首重回。"]},{"t":"聂氏望思堂","f":"五言律诗","c":["远宦违亲养，官居敢自宁。","孤云长入望，万里若为情。","渺渺低淮树，依依带楚城。","狄梁千载意，谁复继芳声。"]},{"t":"赠太医院判韩公达","f":"五言律诗","c":["昆弟俱荣遇，相承领国医。","济人惟药物，种德在书诗。","姓字公卿重，勤劳圣主知。","杏林千树好，雨露日蕃滋。"]},{"t":"送刑部主事郑骆赴宁波知府","f":"五言律诗","c":["进士名无忝，秋官誉更多。","专城膺宠擢，五马动鸣珂。","圣主勤宵旰，斯民赖抚摩。","循良称汉吏，青史久难磨。"]},{"t":"筠庄为西庄吴氏赋","f":"五言律诗","c":["绕庐无杂卉，种竹已成庄。","烟雨三春绿，风泉五月凉。","看时移杖屦，兴至倒壶觞。","日有平安报，题诗咏凤凰。"]},{"t":"题新淦姚氏挹清轩","f":"五言律诗","c":["闭门罕人事，清意有谁知。","山色同朝暮，泉声自四时。","弦琴堪对酒，拄笏好题诗。","为写山林趣，悠然动客思。"]},{"t":"岁暮祀太庙斋宿翰林奉简胡杨二学士 其一","f":"五言律诗","c":["斋宿联官署，俄惊岁又阑。","庭虚灯火静，天迥雪光寒。","渐老怜双鬓，无能愧一官。","相知二十载，许国寸心丹。"]},{"t":"岁暮祀太庙斋宿翰林奉简胡杨二学士 其二","f":"五言律诗","c":["吏散蚤休衙，斋居夜不哗。","盍簪频剪烛，清坐屡供茶。","词赋相如好，才情水部誇。","余生今五十，已觉鬓先华。"]},{"t":"岁暮祀太庙斋宿翰林奉简胡杨二学士 其三","f":"五言律诗","c":["五城风雪暮，万里属残年。","话旧情偏洽，论诗席屡前。","禁钟人语静，高阁漏声传。","未有归田计，聊歌桂树篇。"]},{"t":"岁暮祀太庙斋宿翰林奉简胡杨二学士 其四","f":"五言律诗","c":["岁事秪匆匆，浮生似转蓬。","官居白首共，报国寸心同。","云里天香下，城边霁雪融。","夜深寒不寐，数起候晨钟。"]},{"t":"夏日喜雨写怀 其四","f":"五言律诗","c":["阁中暑不到，长日静无哗。","坐对西垣树，吟看上苑花。","临池常洗墨，汲井自烹茶。","渐觉形容丑，年来两鬓华。"]},{"t":"夏日喜雨写怀 其五","f":"五言律诗","c":["昼永文书静，风清刻漏迟。","云低双阙树，日转万年枝。","感遇交游在，迂疏圣主知。","不才叨翰墨，何以报恩私。"]},{"t":"夏日喜雨写怀 其六","f":"五言律诗","c":["兀兀坐清昼，悠然兴味嘉。","斜风断疏雨，远树障晴霞。","鱼跃动文藻，鸟啼惊落花。","独怜双鬓短，笔砚老生涯。"]},{"t":"夏日喜雨写怀 其七","f":"五言律诗","c":["长日费吟咏，终年典校雠。","宦情真落落，生事只悠悠。","雨后荷花晚，风前麦气秋。","禁林即仙馆，何必问瀛洲。"]},{"t":"夏日喜雨写怀 其八","f":"五言律诗","c":["载笔晨趍阁，庭空暑气清。","云移窗上影，雨送树间声。","近槛驯乌集，当筵舞燕轻。","当时乏经术，衰飒愧吾生。"]},{"t":"夏日喜雨写怀 其九","f":"五言律诗","c":["自谓年非迈，谁知老见侵。","静观天地化，洞识古人心。","积雨生座润，微凉解郁襟。","何时乞恩泽，归老遂投簪。"]},{"t":"夏日喜雨写怀 其十","f":"五言律诗","c":["圣主崇儒术，新开白玉堂。","文章陋秦汉，礼乐洽虞唐。","制作衣冠盛，恢弘运祚昌。","吾儒膺宠遇，献纳愧班扬。"]},{"t":"赠贡士杨綖赴南海训导","f":"五言律诗","c":["杨子青云彦，儒官称好才。","远从南海去，还自日边来。","綵服荣家庆，慈颜乐寿杯。","题诗惭潦倒，临别重徘徊。"]},{"t":"扈从车驾巡边过裴村田舍与杨少傅共酌","f":"五言律诗","c":["清朝催上道，出郭听鸣笳。","野水流冰涧，江风涨雪沙。","清谈驻鞍马，小酌坐田家。","扈跸惭衰迈，祇怜两鬓华。"]},{"t":"晚次白河","f":"五言律诗","c":["日晚白河上，千官向此留。","天光临御幄，云气护宸旒。","柳外轮蹄集，山头猎火收。","故人同寝食，夜语独绸缪。"]},{"t":"早发白河","f":"五言律诗","c":["禁营传四鼓，驱马复晨征。","野旷风威重，天空月影清。","冲冲杂人语，喔喔乱鸡声。","敢惮劳行役，空惭负老成。"]},{"t":"晚次峪口","f":"五言律诗","c":["逦迤从銮驭，山川记昔年。","时巡重讲武，事岂在游畋。","碣石东临海，居庸北枕燕。","帝京浑咫尺，王气满中天。"]},{"t":"营门候驾","f":"五言律诗","c":["羽林初罢猎，万骑拥霓旌。","驰道鸣笳合，前茅列炬明。","充庖惊满载，得隽快先声。","久立瞻銮驭，虹光彻御营。"]},{"t":"廿五日早奉旨同杨少傅先归京","f":"五言律诗","c":["衰年同扈跸，特诏许先归。","出郭星垂野，渡河霜满衣。","远村鸡乱语，斜月雁高飞。","回首天营内，朝阳五色辉。"]},{"t":"同杨少傅蹇夏二尚书过山寺","f":"五言律诗","c":["野寺浑萧索，经行驻马鞍。","饥乌啼树杪，独犬吠云端。","小酌僧同话，新炊客共餐。","题诗记行迹，偶得共盘桓。"]},{"t":"晚同杨少傅蹇夏二尚书宿田家","f":"五言律诗","c":["马头瞻落日，寻宿过田家。","野老欣相得，村醪不用赊。","田园乐丰岁，耕牧足生涯。","摇落秋将尽，因之感岁华。"]},{"t":"梁叔庄墨竹","f":"五言律诗","c":["别馆多幽思，萧萧玉几竿。","玄云动苍石，飞翠拂清湍。","雨露资涵育，冰霜慎保完。","莫忘君子意，抚玩有馀欢。"]},{"t":"为杨学士勉仁题小景","f":"五言律诗","c":["积阴生巨壑，飞翠落崔嵬。","古木云萝暗，苍崖雪瀑开。","幽人挥麈坐，稚子抱琴来。","想有登临兴，看图日几回。"]},{"t":"赠江阴严训导","f":"五言律诗","c":["春宫方进贺，行李又言旋。","冰雪三冬候，关河万里天。","斯文慎自保，交谊久愈坚。","泮水诸生在，瞻思意独悬。"]},{"t":"思亲堂为永丰邹氏赋","f":"五言律诗","c":["患难违乡里，聊兹寄一抔。","江山馀涕泪，雨露感春秋。","宿草寒云重，封丘晚树稠。","昊天思罔极，南望远松楸。"]},{"t":"哭子武安 其一","f":"五言律诗","c":["念尔归何处，呼天竟莫知。","爱深难遽割，抚字独增悲。","魂魄应常在，他生不可期。","一朝成永诀，再见复何时。"]},{"t":"哭子武安 其二","f":"五言律诗","c":["生死嗟何及，徒增父母哀。","肝肠愁欲裂，泪眼痛难开。","近日犹疑在，从今去不回。","但期收尔骨，归葬故山隈。"]},{"t":"哭子武安 其三","f":"五言律诗","c":["尔生才四岁，风骨最堪怜。","已解摊诗卷，还能弄简编。","提携从我后，出入在人前。","命也真如此，朝朝诉彼天。"]},{"t":"挽邵处士","f":"五言律诗","c":["客有邵平者，风流自可人。","江湖曾浪迹，泉石旧为邻。","月暗梅窗夜，烟寒墓草春。","南湖歌楚些，闻者欲伤神。"]},{"t":"送武安同福安柩归西江","f":"五言律诗","c":["弟兄幸同返，相送在东城。","不尽生前意，难胜死后情。","天涯归柩远，万里一舟轻。","回首金台上，吞声泪若倾。"]},{"t":"内阁独坐有感偶成 其一","f":"五言律诗","c":["人事祇如此，蹉跎又一年。","虚名徒窃禄，白首未归田。","秉笔惭周史，临文愧马迁。","太宗遗业在，抚卷重悽然。"]},{"t":"内阁独坐有感偶成 其二","f":"五言律诗","c":["东阁寒初入，垂帘坐夕曛。","乾坤双鬓老，笔砚半生勤。","落叶飘城雪，哀鸿度塞云。","衰迟徒感遇，忝窃愧斯文。"]},{"t":"赠主事刘孟铎还庐陵省亲","f":"五言律诗","c":["京国言归省，庭闱喜具存。","綵衣荣晚节，紫诰沭深恩。","婉娩承甘旨，从容候凊温。","遥知称寿处，宾客日填门。"]},{"t":"挽南昌李良卿夫妇 其一","f":"五言律诗","c":["早客西江外，鼋山竟未归。","望迷先垄远，梦与故乡违。","鹤化悲秋月，牛眠对落晖。","欲题高士传，抚卷重歔欷。"]},{"t":"挽南昌李良卿夫妇 其二","f":"五言律诗","c":["内助资贤淑，闺闱仰德仪。","贻家敦俭朴，阅世享期颐。","竹暗秋风冷，萱残夕露滋。","百年同穴意，埋石有铭词。"]},{"t":"挽礼部侍郎蒋良夫","f":"五言律诗","c":["君是我同年，词林谊独全。","南宫去几日，别馆已闻仙。","空负严亲望，犹兴圣主怜。","今朝归旅榇，惆怅惨风烟。"]},{"t":"喜克超袁君至","f":"五言律诗","c":["远道逾三月，今朝抵玉京。","相持喜不定，倾倒若为情。","问事知乡曲，因风想弟兄。","灯前谩酬劝，不觉过深更。"]},{"t":"挽杨子恭先生 其一","f":"五言律诗","c":["先生清介士，抱道独深藏。","傲世非关僻，潜名岂自强。","山林成独往，鱼鸟自相忘。","前辈风流尽，悲吟只慨慷。"]},{"t":"挽杨子恭先生 其二","f":"五言律诗","c":["雅操冰同洁，高怀鹤共清。","吟诗自可老，避世岂谋生。","遗后铭先著，知归葬自营。","九原去已远，无复见仪型。"]},{"t":"甥光烈自蔚州归喜而赋此","f":"五言律诗","c":["昨夜灯花结，今朝喜鹊声。","忽闻行李至，忧思一时平。","关塞聊须到，山川记此行。","壮游真不薄，期尔早知名。"]},{"t":"挽袁君南恕 其一","f":"五言律诗","c":["平生称旷达，削迹谢浮荣。","诗酒堪娱老，田园足治生。","看山时览眺，闭户少逢迎。","万里闻哀讣，难胜故旧情。"]},{"t":"挽袁君南恕 其二","f":"五言律诗","c":["避俗人皆弃，安贫世共遗。","临风歌对酒，倚竹坐题诗。","雨冷閒松榻，灯昏冷蕙帷。","青山对马鬣，引领泪交颐。"]},{"t":"赠友人还万安","f":"五言律诗","c":["旧隐五云下，翩然又赋归。","秋风三径菊，春日北山薇。","牛渚云连树，龙河雪满衣。","岁华看渐暮，忍见雁南飞。"]},{"t":"赠福建陈学正省亲","f":"五言律诗","c":["凉风日夜起，送客不胜情。","黄叶雨中落，断鸿云外声。","故乡千里远，行李一身轻。","应想趋庭日，争看彩服荣。"]},{"t":"赠舒城朱知县","f":"五言律诗","c":["为说舒城宰，廉声满帝乡。","化行推单父，种德比甘棠。","天阙风云会，瑶阶雨露香。","丹心期补报，致治效虞唐。"]},{"t":"题爱同堂卷","f":"五言律诗","c":["严亲久沦没，慈母幸康宁。","鞠育同恩爱，悲欢异死生。","倚门犹慰意，陟岵不胜情。","锡类资纯孝，乡闾有令名。"]},{"t":"题萧氏虎溪卷","f":"五言律诗","c":["长溪如虎踞，卜宅自何年。","水影通帘幕，云光照简编。","晚凉开竹径，春暖种芝田。","何日寻幽隐，清谈煮石泉。"]},{"t":"题曾原太友琴轩","f":"五言律诗","c":["良朋不可得，雅好托桐君。","白雪心难变，金兰谊独亲。","高山千载意，流水四时春。","古道今寥落，空怀大雅人。"]},{"t":"题南康马教授匡山书屋","f":"五言律诗","c":["匡山渺何许，结屋在云边。","泉响通书幌，岚光照简编。","涧猿听夜诵，林鹤伴朝弦。","奋步追高躅，明当继昔贤。"]},{"t":"题襄阳司训黄公器竹居","f":"五言律诗","c":["脩竹净如洗，翛翛数百竿。","捲帘通翡翠，散帖映琅玕。","凉月分秋色，炎风生昼寒。","知君慕高节，独立倚云端。"]},{"t":"题兰谷","f":"五言律诗","c":["种兰在幽谷，清绝少人过。","香露侵衣润，光风拂席多。","瑶琴无俗韵，澧浦有遗歌。","芳室薰融久，应知德不磨。"]},{"t":"赠周彦奇佥宪云南","f":"五言律诗","c":["远别向滇阳，华筵酒满觞。","骊驹方载道，白简已飞霜。","塞外碧鸡近，云间鸟道长。","远人今向化，努力辅藩方。"]},{"t":"题行素轩","f":"五言律诗","c":["之人安素履，守分独无营。","风月閒中趣，琴书物外情。","捲帘流水近，欹枕白云生。","扰扰奔驰者，何劳身后名。"]},{"t":"赠萧主事之官北京","f":"五言律诗","c":["故人膺宠命，改调理刑曹。","恩露沾新绶，天香染旧袍。","征帆迷雪树，去路接云涛。","到日重回首，遥瞻魏阙高。"]},{"t":"赠徐中书崇威还家","f":"五言律诗","c":["京华岁将暮，谒告独还家。","客路霏霏雪，寒梅处处花。","綵帘娱爱日，寿酒酌春霞。","回首隔蓬岛，相思梦更赊。"]},{"t":"赠友人考满复任","f":"五言律诗","c":["三年初上考，千里独还官。","驿路梅开尽，都门岁易残。","棹歌江上发，山色雪中看。","莫道卑栖久，飞腾总不难。"]},{"t":"挽杜若洲 其一","f":"五言律诗","c":["驱驰二十载，宁复叹官卑。","硕德乡人重，清名海郡知。","沧洲存旧业，墓石有新词。","春草年年绿，思君总是悲。"]},{"t":"挽杜若洲 其二","f":"五言律诗","c":["先生高世士，早岁已知名。","白发悲游宦，遗文叹老成。","故山秋鹤怨，宰树暮猿声。","令子能传业，徵词为勒铭。"]},{"t":"挽德清屠诚","f":"五言律诗","c":["去京能几日，忽复讣音来。","玉树伤先殒，芝兰痛遽摧。","忆归常问事，惜别屡持杯。","惆怅湖山外，伤心泪满腮。"]},{"t":"孟秋时享斋宿翰林","f":"五言律诗","c":["官署清凉后，清心坐夜分。","钟声云外下，玉漏雨中闻。","茶熟银瓶注，香消金鸭焚。","扬雄生事拙，白发愧能文。"]},{"t":"题南园琴趣","f":"五言律诗","c":["閒居慕恬旷，雅趣在南园。","山水留遗韵，烟霞隔世喧。","幽兰宜独操，大雅共谁论。","我亦知音者，何时一过门。"]},{"t":"题清碧书舍","f":"五言律诗","c":["爱子读书处，幽怀孰与同。","青山当户牖，绿树隐帘栊。","濯足过秋渚，鸣琴坐涧松。","故居回首日，总在画图中。"]},{"t":"赠太仆寺丞吴鉴复任滁阳","f":"五言律诗","c":["阙下久蜚声，还官荷圣明。","凉风生祖席，疏雨湿行旌。","秋晚骅骝健，天高鸿雁鸣。","滁阳山水好，图画有馀情。"]},{"t":"赠郁林州判","f":"五言律诗","c":["郁林渺何许，远在海西头。","念子有行色，离情逐宦游。","晓云随綵旆，夜月引仙舟。","好为宣王化，从容展壮猷。"]},{"t":"赠龚子谏佥宪云南","f":"五言律诗","c":["万里南云道，君行佐臬司。","交游怜宿昔，远别系深思。","衣绣瞻飞鹗，乘骢问碧鸡。","遐荒宣德意，揽辔重询咨。"]},{"t":"赠人游钱塘","f":"五言律诗","c":["钱塘古名胜，念子事重游。","湖山迎画舫，海月映红楼。","锦树千堤晓，银涛八月秋。","几时寻贺监，一笑解吴钩。"]},{"t":"赠知县任连江","f":"五言律诗","c":["拜命出瑶京，郎官动列星。","马嘶惊远道，鹏运起沧溟。","越树连云白，闽山入眼青。","到官敷善治，抚字念疲氓。"]},{"t":"题西园清兴","f":"五言律诗","c":["伊人慕清赏，旧隐在西园。","竹影自临砌，泉声时到门。","看云晨拄笏，乘月夜闻莺。","一自膺名宦，幽怀孰与论。"]},{"t":"丰乐堂为周宜民赋","f":"五言律诗","c":["海内隆平日，皇恩遍迩遐。","大田多黍稌，比屋见桑麻。","旆旆誇盈廪，穰穰庆满家。","芹湖羹饭美，尚拟泛云槎。"]},{"t":"北征随驾誓师鸣銮戍","f":"五言律诗","c":["周宣驱猃狁，汉室靖楼烦。","战伐需良将，神谋仰至尊。","皇威开大漠，仙伏御曾氛。","壮士心如虎，争图报国恩。"]},{"t":"题胡宏仲奉萱堂","f":"五言律诗","c":["堂谖久无恙，阿母晚尤康。","鹤发春云重，潘舆爱日长。","花前滫瀡具，膝下綵衣香。","节孝敦流俗，门闾倍有光。"]},{"t":"题习编修梅坡卷","f":"五言律诗","c":["种得梅千树，盈盈雪满坡。","捲帘疏影乱，拂席暗香多。","东阁临风玩，西湖载酒过。","高情政如许，赋罢一高歌。"]},{"t":"题扇赠郭慎思","f":"五言律诗","c":["山光澹如洗，野色净氛埃。","流水缘溪出，柴门隔坞开。","白云生涧曲，绿树荫莓苔。","为问抱琴者，相过日几回。"]},{"t":"题李惟瞻修德斋","f":"五言律诗","c":["端居谢尘鞅，力学慕先民。","独进功尤密，勤修业自新。","咏归川上晚，弦诵雨中春。","抚卷看遗墨，怀人重怆神。"]},{"t":"赠萧性善还家省亲","f":"五言律诗","c":["违隔双亲久，归心一夜生。","綵衣天上别，画舫月中声。","未说珍鲑美，先占喜鹊鸣。","升堂展家庆，重九酒须倾。"]},{"t":"塞外初度日感怀","f":"五言律诗","c":["余生过四十，深恐负前期。","报国当今日，思亲在此时。","功名犹未立，鬓发欲成丝。","兀坐无聊赖，长歌意转悲。"]},{"t":"元夕赐观灯","f":"五言古诗","c":["圣主敷文德，朝廷戢武功。","熙辰千载遇，乐事万方同。","令节逢元夕，灵鳌驾碧空。","危峰遥对峙，䆳谷密相通。","火树千花粲，星桥万点红。","葩分金错落，枝缀玉玲珑。","翡翠妆珠阙，琉璃恍贝宫。","鱼龙陈仗外，鸾鹤下云中。","杂遝群歌进，喧腾百戏工。","观游来稚耋，朝会集华戎。","貔虎森飞将，貂蝉列上公。","炉烟三岛合，香雾九霄濛。","凤辇当晴汉，鸾旗簇暖风。","碧纱围菡萏，绣幄透芙蓉。","露掌承华盖，银桥亘綵虹。","丹青开列嶂，罗绮艳芳丛。","夜久祥光动，春迟淑景融。","御筵称寿酒，玉陛拜重瞳。","果熟瑶池献，莲开宝幛笼。","踏歌声款款，叠鼓韵逢逢。","海宇逢时泰，闾阎乐岁丰。","讴吟纷载路，抃舞效呼嵩。","汉代衣冠盛，周家礼乐崇。","两京陪扈从，千载幸遭逢。","自感恩荣盛，宁知刻漏终。","愿陈天保什，永世播无穷。"]},{"t":"和胡学士立春日韵","f":"五言古诗","c":["雪压残年暮，惊逢万里春。","趍朝瞻昩爽，庆会及芳辰。","日月开黄道，云霞焕紫宸。","御炉香细细，玉佩响振振。","轩冕临丹陛，箫韶合大钧。","班行分鹭序，冠剑集鱼鳞。","福履臻遐寿，嘉祥协至仁。","从兹阳德盛，行睹岁华新。","忝作词垣客，惭非献颂臣。","宴酣歌湛露，深荷宠恩频。"]},{"t":"端午内苑赐观击毬射柳","f":"五言古诗","c":["紫苑东华北，霓旌拂曙来。","锦装千队合，仗列两朋开。","剑戟明初日，衣冠映上台。","櫜鞬屯虎士，匼匝引龙媒。","花簇金毬度，云随綵仗回。","抗弦轻斮柳，飞鞚不生埃。","闪闪扬旗过，逢逢叠鼓催。","夺幖争决胜，得意每先回。","光禄筵初罢，瑶池宴屡陪。","御香霏晓雾，大乐殷春雷。","圣德同天地，恩光被草莱。","风云俱际会，文武属良材。","北斗尊宸极，南山进寿杯。","太平歌既醉，忝窃愧非才。"]},{"t":"分题得钟山霁雪送友人还江右","f":"五言古诗","c":["危峰犹积雪，众壑已清晖。","野迥初澄霁，冬严渐解威。","鸣崖锵佩玦，糁径晃珠玑。","树老擎偏重，泉寒落正微。","阳林浑欲尽，阴谷未全晞。","樵客行应滑，栖禽暖乍飞。","山空惊岁晏，腊尽觉春归。","自愤趍朝惯，那堪故旧违。","一尊倾客路，匹马出京畿。","惆怅难为别，临分重把衣。"]},{"t":"喜雪应制","f":"五言古诗","c":["新冬初届候，瑞雪已先呈。","历乱腾空密，飘飖着地轻。","凝华连禁闼，积素隐雕楹。","未觉瑶池满，旋看辇路平。","侵衣明佩玦，入户散瑶琼。","日下银为屋，天边玉作城。","穿林疑有影，坠竹不闻声。","滉瀁欺歌扇，悠扬湿翠旌。","闾阎多喜气，中外洽欢情。","宇宙氛埃净，山川瘴疠清。","两仪资燮理，群物赖生成。","一统乾坤壮，中天日月明。","有年臻瑞庆，嘉谷兆丰盈。","四海期康阜，邦家协永宁。"]},{"t":"咏雪分韵得珂字","f":"五言古诗","c":["旅馆年将暮，都城雪更多。","低回飘苑树，历乱集庭柯。","杂霰沾衣袖，随风拂佩珂。","天空连浩荡，野迥接坡陁。","沧海收初日，层城眩夕波。","积深藏薜荔，堕下压松萝。","盈尺将平砌，凝澌欲冻河。","映梅纷的皪，缀柳自鬖髿。","近向尊前落，斜窥隙穴过。","瑶池银作水，禁署玉为坡。","委巷封车辙，填门失蚁窠。","捲帘轻可扑，入手净堪挼。","滉漾惊乌鹊，缤纷掩素娥。","重重胜楚练，粲粲拟吴醝。","谷口迷樵径，汀前失钓蓑。","归人先罢市，织妇早停梭。","影夺琼田鹤，光翻墨沼鹅。","映窗书可把，拈笔砚频呵。","出郭愁驱马，趍朝畏满靴。","不嫌毡独冷，已觉鬓先皤。","陶谷情偏洽，苏卿节不磨。","梁园曾授简，郢客尚传歌。","瑞气方融结，祥光欲荡摩。","紫宸明玉座，琐闼净雕戈。","润物功弥博，均施德匪颇。","三农占岁稔，四海颂时和。","自足消氛祲，从兹去札瘥。","作诗惭鄙拙，才薄柰予何。"]},{"t":"瑞雪诗","f":"五言古诗","c":["盛业开千祀，皇威肃万方。","一阳初届候，三白已呈祥。","尽夕迷蟾影，连朝隐旭光。","铺桥明螮蝀，覆瓦失鸳鸯。","辇路琼瑶衬，朝宫宝玉妆。","轻盈飘广陌，宛转度回廊。","川岳同高下，乾坤接混茫。","斗奇宫树侧，呈巧御阶傍。","帘捲琪花湿，车行缟带长。","雕楹斜点染，绣槛远悠扬。","重压虬松偃，深埋虎石藏。","联翩沾几席，散漫集琼珰。","沛泽滋群品，氛埃净八荒。","从天消瘴疠，入地殄螟蝗。","百辟欢逾洽，三农喜莫当。","九重颁圣制，五彩焕天章。","宗社鸿图远，朝廷运祚昌。","作诗歌圣德，永世绍虞唐。"]},{"t":"古图山水","f":"五言古诗","c":["平生爱山水，对此意无穷。","远树参差合，流泉屈曲通。","花明红雨落，谷暗白云封。","鹿饮过青涧，猿啼隐碧峰。","鸟归秋崦外，人语夕阳中。","为问武陵客，桃源何处逢。"]},{"t":"钦惟圣天子嗣大历服简用旧人懋图治理覃布恩德绥怀万方天地清宁海宇乂安乃以宣德戊申二月廿八日命少师吏部尚书臣蹇义臣幼孜等凡十有八人乘马将仆?从游万岁山已又命乘御舟泛太液池遍历小山诸处维时风日暄朗景物明丽氛埃屏息佳气郁葱心目舒畅得以周览奇胜复蒙天语从容慰劳赐以醇醪珍馔俾尽饮至醉恩意深厚宠赐便蕃诚终身之荣幸千载而一遇者也臣幼孜无任感激之至谨赋五言长律一首上进伏乞圣览不胜幸甚诗曰","f":"五言古诗","c":["朝廷多暇日，诏许从宸游。","联骑经东苑，挥鞭过御沟。","渐瞻琼岛近，夐对小山幽。","巀嵲凌霄汉，清虚动斗牛。","盘承金露重，栋拂玉虹流。","叠石苍苔合，悬崖古木稠。","林高巢巨鹘，壑邃舞潜虬。","驰道回鸾驭，花阴驻紫骝。","空中香雾满，日下紫氛收。","太液相环抱，波光欲荡浮。","泓涵通碧海，澄澈透灵湫。","翠荇翻红鲤，轻澜泛白鸥。","碧桃晴雨润，杨柳暖风柔。","忽喜传天语，联翩载御舟。","醇醪分玉斝，香茗溢金瓯。","冠盖随云气，歌谣应棹讴。","迂回循岸曲，逦迤历城陬。","真似经三岛，犹疑访十洲。","烟霞围胜境，日月驻丹丘。","列籍依芳树，开筵望翠斿。","九重颁异果，多品列珍羞。","击节谐欢笑，持觞屡劝酬。","遭逢恩独厚，感激赐还优。","圣德乾坤大，神功舜禹侔。","华夷覃霈泽，遐迩戴鸿休。","治世雍熙盛，优贤礼数周。","不才叨侍从，末学乏谟谋。","幸数承清问，常时近冕旒。","虚心勤至道，当宁纳嘉猷。","再拜陈篇什，皇图衍万秋。"]},{"t":"和答庶吉士杨之宜就柬宗豫大学士士奇谕德及翰林诸同志 其一","f":"七言律诗","c":["西风露下碧漙漙，久别羁怀有万端。","游子自惊乡梦远，慈闱应念客衣寒。","云连南浦低回雁，木落空江涌浩澜。","东阁故人如见忆，新诗还许寄来看。"]},{"t":"和答庶吉士杨之宜就柬宗豫大学士士奇谕德及翰林诸同志 其二","f":"七言律诗","c":["广寒宫阙载丹丘，揽辔亲随御辇游。","林外好花多映日，涧边瑶草不知秋。","恍疑飞步凌三岛，绝胜吹笙过十洲。","此日登临膺宠渥，相思不见重离愁。"]},{"t":"和答庶吉士杨之宜就柬宗豫大学士士奇谕德及翰林诸同志 其三","f":"七言律诗","c":["都门翘首思如飞，万里乡山入望微。","久客情怀随处好，故人书札近来稀。","江南落日孤云远，旅馆西风一雁归。","昨寄黄庭缄远意，使来应想达京畿。"]},{"t":"和答庶吉士杨之宜就柬宗豫大学士士奇谕德及翰林诸同志 其四","f":"七言律诗","c":["太平海宇被皇风，御辇时巡出九重。","献纳极惭才力薄，遭逢更荷圣恩浓。","未忘退直联车骑，犹忆同朝听早钟。","回首帝京天咫尺，钟山云气尽成龙。"]},{"t":"和答庶吉士杨之宜就柬宗豫大学士士奇谕德及翰林诸同志 其五","f":"七言律诗","c":["日射天门乌乱啼，朝回祇在掖垣西。","玉堂视草回鸾驭，内苑看花散马蹄。","太液波光临阙近，西山云气入帘低。","欲知别后承恩好，时有天香满袖携。"]},{"t":"和答庶吉士杨之宜就柬宗豫大学士士奇谕德及翰林诸同志 其六","f":"七言律诗","c":["十年谬忝戴朝簪，岁月欺人老易临。","报国未酬明主意，托交深识故人心。","太平制作过前辈，早岁声华在禁林。","何日西窗同剪烛，尊前夜雨听新吟。"]},{"t":"和答庶吉士杨之宜就柬宗豫大学士士奇谕德及翰林诸同志 其七","f":"七言律诗","c":["扈跸叨陪侍从臣，后车宁敢附麒麟。","三春跋涉秦淮道，万里经行析木津。","薄宦十年违梓里，丹心此日系枫宸。","南来冠盖多如雨，欲赋长杨愧后尘。"]},{"t":"和答庶吉士杨之宜就柬宗豫大学士士奇谕德及翰林诸同志 其八","f":"七言律诗","c":["春风跃马上燕台，一览江山亦快哉。","盛世遭逢叨宠眷，微生报答愧非才。","已从琼岛看花去，还忆长杨献赋来。","早晚元戎清朔漠，先期扈跸日边回。"]},{"t":"和答庶吉士杨之宜就柬宗豫大学士士奇谕德及翰林诸同志 其九","f":"七言律诗","c":["金水桥东谩卜居，趍朝日日侍皇舆。","心悬北阙青云近，日接南天树影疏。","远客风流应未减，诸公文采复何如。","痴儿无事烦深念，懒钝宁能读父书。"]},{"t":"随驾至昌平登万寿山","f":"七言律诗","c":["万里平原入渺茫，淡烟疏雨晓苍苍。","河流北下连沧海，山势西来接太行。","小洞人家鸡犬静，云边石室水泉香。","经行不异桃源境，驻目凭高意转长。"]},{"t":"和胡祭酒快雪喜晴之作","f":"七言律诗","c":["黄云万里夐相连，六出飞花点座毡。","冻合龙楼初试火，寒侵鹤氅欲添绵。","御沟滉漾银波静，琼岛微茫霁景鲜。","最是玉堂清似水，捲帘呵笔写鸾笺。"]},{"t":"禁中对雪和邹侍讲韵","f":"七言律诗","c":["都门向晓雪交飞，独步偏宜鹤氅衣。","天近蓬莱银作屋，地回粉署玉为扉。","洒窗更恐疏帘过，拂帽还将短袖挥。","已卜丰年多瑞应，一尊共赏莫相违。"]},{"t":"再和曾侍讲韵","f":"七言律诗","c":["冻云压地晓寒清，剪出瑶花片片轻。","撩乱欲迷鳷鹊观，霏微远度凤凰城。","湘帘半捲飞还落，辇道经行扫更平。","向晚玉堂光可烛，细看书卷独分明。"]},{"t":"和答祭酒胡公移居","f":"七言律诗","c":["故人远自西江至，借得幽居意自新。","茶灶笔床忘俗虑，纸窗石榻净氛尘。","宾朋问候时相过，鸡犬移来久自驯。","共喜北来风景好，霜晴十月暖如春。"]},{"t":"退朝口号和答祭酒胡公","f":"七言律诗","c":["金阙嵯峨耸巨鳌，庆云五色护龙袍。","西山瑞雪浮佳气，太液微风飏碧涛。","载笔每闻天语近，退朝还睹日华高。","玉堂承诏多清暇，歌咏犹能试彩毫。"]},{"t":"十月三十日思亲","f":"七言律诗","c":["生我于今四十年，每怀报德负苍天。","身留北阙违桑梓，望尽南原隔墓田。","郡有清名传死后，人怀遗爱在生前。","客居此日偏多感，洒泪西风独惘然。"]},{"t":"次许鸣鹤至日韵","f":"七言律诗","c":["初阳隐隐动微和，卜岁占云竟若何。","天近九重香雾暖，日回万井瑞烟多。","北来旅寓随萍梗，南望乡山隔薜萝。","共沐圣朝恩渥重，且须对酒一高歌。"]},{"t":"冬十一月廿三日随驾阅武于齐化门外","f":"七言律诗","c":["圣主从容事阅兵，銮舆向晓出都城。","三军勇悍今无敌，万骑骁腾旧有名。","牙帐风生鸣鼓角，期门日暖动旄旌。","早须汉北销氛䘲，海晏河清颂太平。"]},{"t":"读文丞相传有感","f":"七言律诗","c":["忆昨中原板荡秋，衔哀日夜在兴周。","全生不为功名计，后死空怀社稷谋。","皎皎丹心明日月，巍巍大节重山丘。","北来吊古看馀录，祇在当时已泪流。"]},{"t":"晚归自玉堂偶成","f":"七言律诗","c":["词林退直过昏鸦，缓辔垂鞭踏月华。","风急断鸿低粉堞，天寒羸犊困柴车。","谁家步幛随丝管，何处铙歌杂鼓笳。","渐喜客居生意好，底须物外避諠哗。"]},{"t":"皆山轩为太仆寺丞吴性泉赋","f":"七言律诗","c":["滁上幽居尽日閒，捲帘面面对青山。","烟中树色自远近，天际浮云时往还。","酒醒闻莺过别墅，兴来洗马坐松间。","故知吏隐多真率，何日相从一解颜。"]},{"t":"和韵答梁修撰 其一","f":"七言律诗","c":["风清驰道散香尘，日共趍朝侍紫宸。","琼岛雪寒犹待腊，御沟冰泮已回春。","异乡慰藉烦朋友，久客暌离念老亲。","惭愧菲才叨宠遇，深期报答在兹辰。"]},{"t":"和韵答梁修撰 其二","f":"七言律诗","c":["煇煇旭日照高台，暖气还从上谷回。","香雾细薰池上草，红霞低映水边梅。","故人病起耽诗句，羁旅豪来纵酒杯。","总道残年霜雪少，春光先已到蓬莱。"]},{"t":"和韵答梁修撰 其三","f":"七言律诗","c":["禁城雪后暖初生，草树凝晖炫晓晴。","仗簇青云开雉扇，香通紫禁度鸾笙。","中天日月悬双阙，一统山河奠两京。","幸喜承恩偕扈跸，朝回时共散珂声。"]},{"t":"凝清堂为姚府尹赋","f":"七言律诗","c":["玉雪襟怀鹤氅轻，画堂燕坐有馀清。","捲帘自爱青山好，隐几不闻啼鸟声。","日转暖云当户静，雨馀碧草上阶生。","就中此意谁能识，岁久应知太守情。"]},{"t":"赠太仆吴寺丞还滁阳","f":"七言律诗","c":["昨来呈马御楼前，五色龙文照锦鞯。","喜见承恩来日下，忽看行李出天边。","河流夜绕卢沟月，关树晴连白塔烟。","腊尽春归能几日，到官应是及新年。"]},{"t":"次若思胡祭酒立春日早朝","f":"七言律诗","c":["客里残年逢立春，清宵待漏拜枫宸。","玉阶旗影飘晴雪，驰道珂声动紫尘。","綵燕斗簪幡胜好，芹芽试簇菜盘新。","銮舆暂退闻呼唤，赐宴先传及近臣。"]},{"t":"次罗修撰元旦纪事","f":"七言律诗","c":["漏声未彻禁钟催，绛阙熹微曙色开。","仙乐近从三殿出，香烟还傍九霄来。","西山王气连蓬岛，南极恩光被草莱。","此日履端同献寿，阳春属和羡多才。"]},{"t":"次胡祭酒元日早朝","f":"七言律诗","c":["未明卤簿已先陈，凤盖鸾旗五色新。","银烛影含双阙晓，箫韶声合九重春。","金函奉表来群辟，卉服随朝进远人。","共祝尧年歌圣德，燕南万里净风尘。"]},{"t":"和子启曾侍讲元日早朝","f":"七言律诗","c":["金炉袅袅瑞烟轻，银烛煌煌拂曙明。","天转蓬莱红日近，春回阊阖暖霞生。","九霄斧钺开仙仗，万国衣冠会玉京。","忝列鹓行称圣寿，三台遥睹泰阶平。"]},{"t":"喜友人郭子成赴召至京夜宿旅舍赋此奉柬","f":"七言律诗","c":["暌离已是五年馀，又复相逢在客居。","白首谁怜多患难，丹心自许效驰驱。","金台夜月生归梦，鲸水秋风忆故庐。","此夕旅怀应尽解，不须对酒重欷歔。"]},{"t":"黄公宗豫元夕请赏莲花灯次光太胡公韵","f":"七言律诗","c":["锦簇星房巧样新，画堂不夜暖生春。","琼杯贮露承仙掌，绛幕流霞度暗尘。","艳质交辉风度席，红妆低照月随人。","年年此夕陪清燕，倾倒宁辞醉脱巾。"]},{"t":"赠王尹实判官还潞州","f":"七言律诗","c":["三年京国数追游，千里还官宠渥优。","诗兴谩从佳士发，篆书多为故人留。","山城腊尽梅初放，驿路春寒雪未收。","早晚到州如有暇，新诗先寄凤池头。"]},{"t":"赠袁士诲之官孝感","f":"七言律诗","c":["与君相见还相别，又捧天书出紫宸。","江上月移仙棹远，花前日照锦袍新。","河阳旧日民怀惠，柏府当年政有神。","自昔郎官当列宿，为言抚字在忠勤。"]},{"t":"赠赤水张经历矩秩满还官","f":"七言律诗","c":["昔年相见忝诸生，此日重逢愧老成。","紫陌看花同是客，灯前对酒若为情。","湘江水暖春来绿，蜀道云开雪后晴。","此去辕门勤赞画，伫看鹗荐有公卿。"]},{"t":"和答光太胡学士至日喜雪之作","f":"七言律诗","c":["微阳初动煖生灰，晨雪霏霏应候来。","渐觉飞花迷粉署，忽惊舞絮满琼台。","银河有影光初合，金水无声冻不开。","总道丰年三白好，且须酌酒劝深杯。"]},{"t":"和若思胡祭酒至后咏怀 其一","f":"七言律诗","c":["学省朝回无一事，钩帘坐看雪飞花。","故人问字或载酒，稚子敲冰时煮茶。","东阁十年同载笔，西江千里共思家。","昨朝葭琯阳初动，时觉新袍煖渐加。"]},{"t":"和若思胡祭酒至后咏怀 其二","f":"七言律诗","c":["花树凝晖散彩霞，禁梅融雪吐轻花。","玉堂进讲仍分直，光禄传餐更赐茶。","报国自期心似铁，浮生已分客为家。","太平幸际重熙日，喜见新阳霈泽加。"]},{"t":"壬辰会试受命作考试官","f":"七言律诗","c":["恭承诏命简群英，惭以非才秉鉴衡。","五夜奎光垂玉座，九重曙色动霓旌。","明时养士关兴运，此日抡材系圣情。","不独有周歌棫朴，朝阳伫听凤凰鸣。"]},{"t":"二月八日入试院奉柬谕德士奇诸同志","f":"七言律诗","c":["群才济济会南宫，奋笔争趍战艺中。","江海鱼龙乘化雨，云霄雕鹗借长风。","文章自昔归时论，选拔由来合至公。","圣代求贤思治理，共须努力副宸衷。"]},{"t":"青山白云图","f":"七言律诗","c":["十年京国梦林丘，此日披图忆旧游。","窗户烟云晴欲合，楼台苍翠晚初收。","长桥流水通行客，落日沧波起棹讴。","为问玉山渺何许，此身先已到瀛洲。"]},{"t":"竹林书屋为刘子樵赋","f":"七言律诗","c":["万竿苍玉护茅庐，清绝偏宜隐者居。","五月绿阴连户牖，三秋凉翠湿衣裾。","閒裁汗简供吟咏，醉写琅玕入画图。","何日考槃能遂愿，相从三径引柴车。"]},{"t":"分题得黉馆弦歌送萧太守伯辰还深州","f":"七言律诗","c":["太守兴贤费琢磨，诸生岁久沐馀波。","黄堂昼永鞭笞静，泮水春深雨露多。","已喜闾阎兴揖让，屡闻父老诵时和。","州人自此敦风教，不独文翁有咏歌。"]},{"t":"赠石彦诚之官徐闻","f":"七言律诗","c":["故人取别大匆忙，行李朝来发帝乡。","当代求贤思治理，昔人作县重循良。","过家腊尽怀桑梓，度岭春来避雪霜。","海上到时官事少，题诗日日对桄榔。"]},{"t":"赠黄思恭先生受诰还永嘉","f":"七言律诗","c":["回鸾五色散天香，凤翥龙飞粲玉章。","圣主褒封昭盛典，先生拜赐荷恩光。","大夫命服尊乡里，学士官衔压右坊。","此别但期多寿考，永歌天保颂时康。"]},{"t":"挽苏伯厚编修","f":"七言律诗","c":["先生交谊重金兰，十载同朝列从官。","天禄校书知姓字，经筵进讲识衣冠。","花迎旅榇春云暗，树掩铭旌暮雨寒。","目送归魂招不得，忍将别酒酹江干。"]},{"t":"扈从再狩武冈次学士胡公韵 其二","f":"七言律诗","c":["辇道霏霏散紫尘，好风晴日煖先春。","羽林列骑分兵卫，玉帐迎銮引从臣。","香度綵云瞻御气，光涵宝露沐深仁。","太平久协非熊兆，况是清朝集凤麟。"]},{"t":"赠李伯葵还庐陵","f":"七言律诗","c":["二十年前早识君，别来几度想清芬。","沧洲把钓常听雨，林下哦诗只看云。","郎署綵衣留缱绻，画图别意写殷勤。","青原白鹭遥相望，把酒临岐忍共分。"]},{"t":"腊月四日同杨谕德晚出访友人李伯葵余回至长安街坠马遂在告数日胡学士先以诗见寄明日杨复以诗来相嘲因次韵奉答且以自解也然后诗结语盖答杨意也 其一","f":"七言律诗","c":["雪消官道马难行，驾驭由来未可轻。","颠蹶泥涂争失笑，淋漓衣袖益堪惊。","浩歌不尽停云意，高卧何胜恋阙情。","忽得好诗相慰藉，明珠万斛照新晴。"]},{"t":"腊月四日同杨谕德晚出访友人李伯葵余回至长安街坠马遂在告数日胡学士先以诗见寄明日杨复以诗来相嘲因次韵奉答且以自解也然后诗结语盖答杨意也 其二","f":"七言律诗","c":["向晚街头惊坠马，已瞻归骑去翩翩。","溅泥未觉沾乌帽，坠地宁论涴锦鞯。","松火寒炉供夜坐，梅花高阁对朝眠。","未须一蹶伤迟暮，壮志还应迈昔年。"]},{"t":"九日侍从车驾出南郊登高","f":"七言律诗","c":["京华此日逢重九，扈跸登临荷圣情。","万里河山空斥候，三秋禾黍贺收成。","西风旌旆连云影，落日楼台起笛声。","惭愧微生叨宠遇，永歌天保答升平。"]},{"t":"九月十八日扈从车驾出居庸关外较猎","f":"七言律诗","c":["羽士如林亦壮哉，长风万里蹴飞埃。","雕弓射雁云中落，锦臂鞲鹰马上来。","绝壁重重围网近，高峰猎猎竖旗开。","从臣载笔长杨里，谫薄惭无献赋才。"]},{"t":"和子启曾侍讲敕建内阁之作","f":"七言律诗","c":["中天蓬岛郁岧峣，紫殿琼楼近碧霄。","树外远峰晴入阁，花间流水曲通潮。","清朝视草回鸾驭，白昼焚香合凤韶。","共喜临池多暇日，綵云时向座间飘。"]},{"t":"和曾侍讲禁中闻莺","f":"七言律诗","c":["禁城疏雨映红霞，忽听莺声感物华。","天上幽栖偏自在，日边娇语避諠哗。","歌馀白昼閒芳树，啼尽东风送落花。","却忆江南成久别，坐听曾到野人家。"]},{"t":"北京八景 其二 玉泉垂虹","f":"七言律诗","c":["宛宛垂虹引玉泉，萦岩出涧净娟娟。","细通树底映初日，遥转湖阴涵远天。","鱼动翠纹生雨后，鸥翻细浪起风前。","源源自是归沧海，添作恩波遍九埏。"]},{"t":"北京八景 其三 太液晴波","f":"七言律诗","c":["禁苑香风散紫埃，晴波漾日自沿洄。","天光下映银潢净，云影遥涵玉鉴开。","旧日曾随仙仗到，几时还载酒船回。","从知弱水通三岛，应有群仙献寿来。"]},{"t":"北京八景 其四 琼岛春云","f":"七言律诗","c":["蓬莱东望近扶桑，冉冉春云接下方。","隔水楼台通御气，半空草树发天香。","花间驻辇霓旌湿，海上传书鹤梦长。","映日龙文还五色，殿头常得近清光。"]},{"t":"北京八景 其七 卢沟晓月","f":"七言律诗","c":["卢沟杳杳出桑乾，月照河流下石滩。","茅店鸡声斜汉曙，汀沙雁叫早霜寒。","水光微带山烟白，野色遥连塞草残。","千古长桥枕南北，忆曾题柱倚阑干。"]},{"t":"北京八景 其八 金台夕照","f":"七言律诗","c":["迢递金台近日边，偶来登览尚依然。","万家禾黍秋风外，十里旌旗落照前。","远郭砧声来杳杳，平原归骑去翩翩。","黄金谩说能招士，千载犹传郭隗贤。"]},{"t":"元夕赐午门观灯 其四","f":"古风","c":["万朵金莲彻夜开，满帘香雾隔蓬莱。","遥看鳌背云中出，喜见仙人海上来。","拂曙星河低绛阙，凌空鸾鹤上瑶台。","笙歌一?春如海，共进吾皇万寿杯。"]},{"t":"赋玩藻轩","f":"七言律诗","c":["新构华轩小池上，閒来玩藻亦多情。","紫茎荡日绿波动，翠叶翻风细浪轻。","自昔舜裳昭盛美，况闻鲁泮播嘉名。","极知文采归吾辈，育德相期更老成。"]},{"t":"赠许时还文江","f":"七言律诗","c":["共说君家兄弟好，容仪楚楚羡多才。","兄从载笔两京去，弟复将家万里来。","行李暂留残腊住，扁舟却向早春回。","客中相送情难尽，愁赋归鸿对酒杯。"]},{"t":"次用之梁赞善人日观驾之作 其一","f":"七言律诗","c":["森森羽卫肃清晨，扈跸千官候紫宸。","旗拥交龙收宿雨，辇随丹凤辗轻尘。","三阳应候频占岁，七日宜晴自可人。","极知圣德同天运，万汇从兹又一新。"]},{"t":"次用之梁赞善人日观驾之作 其二","f":"七言律诗","c":["朝罢金舆出建章，庆云五采绚晨光。","霓旌拂树开仙跸，宝马穿花散御香。","金水绕梁初泛绿，仙醪贮瓮尚封黄。","镐京侍宴沾恩泽，独对南山献寿觞。"]},{"t":"次用之梁赞善人日观驾之作 其三","f":"七言律诗","c":["幄殿当中锦绣开，千官先进紫霞杯。","花间合乐晴云度，柳下停銮昼漏催。","日丽綵筵金作屋，云回宝仗玉为台。","东风澹荡春先到，已有阳和遍九垓。"]},{"t":"次用之梁赞善人日观驾之作 其四","f":"七言律诗","c":["万乘行春展豫游，忝从载笔荷恩休。","碧桃花重偏迎辇，御柳寒轻不入裘。","天香尽日随冠盖，佳气无时近冕旒。","闻道故人歌咏好，诗成先拟进瀛洲。"]}]};